-- 012: learning library content.
--
-- DRAFT: requires review before launch. Every series and module is inserted with
-- review_status = 'draft'. After a human has reviewed an item, mark it approved, e.g.
--   UPDATE learning_series_modules SET review_status = 'approved' WHERE series_key = '...' AND module_key = '...';
-- Pre-launch check:  SELECT series_key, module_key FROM learning_series_modules WHERE review_status <> 'approved';
--
-- Generated from authored content (Claude-drafted, each module cites its framework).
-- Relationship Foundations (rf-*) and Repair & Communication (rc-*) carry over the lessons
-- previously bundled in mobile/content/series. Replaces the one-line placeholder modules
-- (cn-1, cm-1, ...) seeded by bond_seed.sql.
--
-- Requires 011_content_architecture.sql. Safe to re-run: upserts by key, and removes modules
-- in these series that are no longer part of the library.

BEGIN;

-- Relationship Foundations (8 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('relationship-foundations', 'Relationship Foundations', 'The core research on what helps relationships last: connection, attachment, repair, trust, and shared meaning.', 'Start here. Eight lessons that introduce the ideas the rest of Bond builds on, from turning toward each other and attachment to repair after conflict and building shared meaning.', '🧭', 1, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('relationship-foundations', 'rf-1', 'What Makes Relationships Succeed', 'Explore the science of relationship success and the predictable patterns that distinguish thriving couples.', 'Explore the science of relationship success and the predictable patterns that distinguish thriving couples.', '12 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "Research by relationship scientists shows that healthy relationships are not mostly about luck or perfect compatibility. They are built from repeatable habits: turning toward bids for connection, repairing quickly after conflict, keeping trust visible, and protecting appreciation.\n\nThe big idea is simple: strong relationships are not conflict-free. They are good at recovery.", "sections": [{"title": "The pattern behind thriving couples", "body": "The most resilient couples do not avoid tension. They stay emotionally engaged, even when they disagree. They know each other well enough to interpret stress accurately, and they repair instead of escalating.\n\nThat means the important question is not \"Do we ever struggle?\" It is \"What do we do after we struggle?\"", "research": {"text": "Longitudinal relationship research consistently shows that repair, responsiveness, and positive emotional climate predict stability.", "source": "Gottman & Silver, The Seven Principles for Making Marriage Work", "year": 2015}}, {"title": "The 5:1 ratio", "body": "Thriving couples tend to maintain a strong balance of positive to negative interactions, especially during stress. The exact number is less important than the principle: positive emotion has to stay present enough to keep difficult moments from defining the whole relationship.\n\nSmall appreciation, warmth, humor, and curiosity matter more than people think.", "tip": {"title": "Daily positivity check", "steps": ["Name one thing your partner did well today", "Say one thing you appreciated about how they handled stress", "End one conversation with warmth instead of drifting apart"]}}, {"title": "Repair is the real superpower", "body": "Every couple will misread each other, disappoint each other, and occasionally hurt each other. The difference is whether they know how to come back together.\n\nRepair can be tiny: a softer tone, a good-faith clarification, a pause, a genuine apology, or a bid to reconnect. Small repair attempts are often more important than dramatic breakthroughs.", "example": {"scenario": "One partner feels ignored after a rough evening.", "dialogue": "Partner A: \"I think I came in too sharp. Let me try again. I care about this, and I want to understand you.\"\nPartner B: \"Okay. I needed that reset. Let me explain what I was feeling.\"", "analysis": "Repair did not erase the conflict. It made the conversation safe enough to continue."}}], "conclusion": "Relationships succeed when two people can stay kind, stay curious, and recover together. The goal is not perfection. The goal is a relationship that can absorb stress without losing connection."}'::jsonb, '["Healthy relationships are built, not found", "Repair matters more than avoiding conflict", "Positive emotional climate protects the relationship under stress", "Knowing each other well improves connection and resilience"]'::jsonb, '[{"title": "Repair History", "description": "Review how you recover after conflict.", "duration": "15 min", "instructions": ["Think of the last 3 disagreements", "Write down what helped and what made things worse", "Identify one repair move that actually works for you both", "Agree to use that move the next time tension rises"]}]'::jsonb, '{"question": "What does a healthy relationship feel like to you in real life, not in theory?", "followUp": "What one habit would make your relationship feel more stable this week?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-2', 'Attachment Theory in Adult Relationships', 'Understand how attachment patterns shape closeness, distance, and emotional safety.', 'Understand how attachment patterns shape closeness, distance, and emotional safety.', '15 min', 2, ARRAY['Attachment Theory']::text[], '{"introduction": "Attachment theory explains why closeness can feel soothing to one person and overwhelming to another. In adult relationships, attachment is not a diagnosis. It is a pattern of protection.\n\nOnce you understand that pattern, you can stop personalizing every reaction and start building security on purpose.", "sections": [{"title": "The four common attachment patterns", "body": "Secure partners are comfortable with intimacy and independence. Anxious partners tend to scan for signs of distance and may need more reassurance. Avoidant partners often protect themselves through space and emotional self-reliance. Fearful partners want closeness but do not always trust it.\n\nNone of these patterns mean someone is broken. They mean they learned a way to stay safe.", "research": {"text": "Adult attachment patterns can change through awareness, supportive relationships, and repeated corrective experiences.", "source": "Mikulincer & Shaver, Attachment in Adulthood", "year": 2007}}, {"title": "The pursue-withdraw loop", "body": "A common problem pair is anxious pursuit and avoidant withdrawal. The more one partner pursues reassurance, the more the other may pull back. The more the other pulls back, the more the first person intensifies their effort.\n\nThe issue is usually not lack of love. It is mismatch in how safety gets restored.", "example": {"scenario": "One partner wants immediate reassurance after an argument, while the other wants space before talking.", "analysis": "Both partners are trying to regulate threat, but their coping styles collide."}}, {"title": "How to build earned security", "body": "Earned security comes from doing the thing your nervous system does not expect: staying steady, naming feelings, and making repair predictable.\n\nThat includes saying what you need directly, honoring pauses, following through, and proving through repetition that the relationship can survive discomfort.", "tip": {"title": "Security script", "steps": ["Name what you feel", "Say what you need without blame", "Give your partner a clear way to respond", "Follow through on what you said you would do"]}}], "conclusion": "Attachment patterns are changeable. Security is not about never getting activated. It is about learning how to return to connection faster and with less damage."}'::jsonb, '["Attachment is a protection pattern, not a character flaw", "Anxious and avoidant styles often create a pursue-withdraw cycle", "Security grows through repetition, honesty, and predictable repair", "Direct reassurance and clear space both matter"]'::jsonb, '[{"title": "Trigger Map", "description": "Track what activates your attachment system.", "duration": "20 min", "instructions": ["List 3 moments that make you feel most insecure", "Write what you typically do next", "Ask what your partner would see from the outside", "Choose one calmer response to practice next time"]}]'::jsonb, '{"question": "When you feel threatened in love, do you move closer, move away, or do both at once?", "followUp": "What would a more secure response look like for you?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-3', 'Love Languages and Daily Care', 'Learn how care lands differently for different people and how to use that information well.', 'Learn how care lands differently for different people and how to use that information well.', '10 min', 3, ARRAY['Five Love Languages (Chapman)']::text[], '{"introduction": "Love languages are useful because they remind couples that love is not just about intent. It is also about reception.\n\nYou can mean well and still miss the mark. The fix is not more effort in the abstract. It is more accuracy.", "sections": [{"title": "Five ways love is commonly felt", "body": "Words, time, gifts, acts, and touch are all valid pathways to feeling cared for. Most people have one or two that land more deeply than the others.\n\nThe mistake couples make is assuming their own preferred style is universal. It is not."}, {"title": "Why mismatch matters", "body": "A mismatch does not mean the relationship is weak. It means one partner may be offering care in a language the other does not register as easily.\n\nThis is why a person can be deeply loved and still feel unloved if the expression does not match their preference."}, {"title": "Using the result well", "body": "Your results should not become a scoreboard. They should become a care map.\n\nThe best use of the data is simple: give more in the language your partner receives, and explain your own needs clearly enough that your partner can actually meet them.", "tip": {"title": "One-week love-language practice", "steps": ["Pick one love language for each partner", "Do one intentional act in that language every day", "Notice what lands most strongly", "Talk about what felt most meaningful at the end of the week"]}}], "conclusion": "Love languages work best when they become a daily practice of translation, not a one-time label."}'::jsonb, '["Love languages describe how care is received, not just given", "Mismatch is common and fixable", "The best result is a care map, not a ranking"]'::jsonb, '[{"title": "Care Translation", "description": "Turn one generic loving habit into a specific gesture that your partner feels.", "duration": "10 min", "instructions": ["Write one way you usually show love", "Rewrite it in your partner’s preferred language", "Do it once within 48 hours"]}]'::jsonb, '{"question": "What do you do out of love that your partner may not automatically feel as love?", "followUp": "What do you most want your partner to do more consistently?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-4', 'Conflict and Repair', 'Learn why conflict is normal and how repair keeps hard moments from becoming relationship damage.', 'Learn why conflict is normal and how repair keeps hard moments from becoming relationship damage.', '12 min', 4, ARRAY['Gottman Method']::text[], '{"introduction": "Conflict is not a sign that a relationship is failing. It is a sign that two real people with needs, limits, and histories are trying to build a life together.\n\nThe question is never whether conflict will happen. The question is whether you can repair without making each other feel unsafe.", "sections": [{"title": "Why conflict is not the enemy", "body": "Many couples try to avoid conflict entirely, but avoidance often leaves important issues unresolved. Healthy couples do not stay perfectly calm. They stay engaged enough to keep talking.\n\nThe problem is not disagreement. The problem is contempt, defensiveness, stonewalling, and escalation that makes repair harder later.", "research": {"text": "Conflict style matters less than whether partners can recover, de-escalate, and stay respectful while disagreeing.", "source": "Gottman research on marital stability and repair", "year": 2015}}, {"title": "Repair moves that actually work", "body": "Repair attempts are small signals that say, \"I am still with you.\" They can be as simple as softening your tone, naming your part, or asking to restart the conversation.\n\nThe key is that repair happens early enough to matter. Waiting too long usually makes both people more rigid.", "tip": {"title": "Repair menu", "steps": ["Pause and lower your volume", "Name one thing you can own", "Ask one curious question", "Restate the real issue in one sentence"]}}, {"title": "A simple repair sequence", "body": "A good repair sequence is predictable: notice the rupture, lower intensity, name the need, and reconnect around the issue instead of around blame.\n\nThat sequence is boring in the best way. It works because it makes safety feel repeatable.", "example": {"scenario": "One partner shuts down after feeling criticized.", "dialogue": "Partner A: \"I got too sharp. Let me try that again without the edge.\"\nPartner B: \"Thank you. I can stay in this conversation if we slow it down.\"", "analysis": "Both partners are choosing connection over winning, which lowers threat immediately."}}], "conclusion": "Conflict becomes workable when repair is faster, clearer, and more respectful than the escalation that came before it."}'::jsonb, '["Conflict is normal; damage is optional", "Repair attempts should come early and often", "Respectful disagreement is a skill, not a personality trait", "Small resets matter more than perfect arguments"]'::jsonb, '[{"title": "Repair Practice", "description": "Rehearse one repair line you can use in real life.", "duration": "10 min", "instructions": ["Pick one recurring conflict pattern", "Write the repair line you wish you used sooner", "Practice saying it out loud", "Agree to use it the next time things start to escalate"]}]'::jsonb, '{"question": "What do you usually do first when conflict starts: defend, explain, withdraw, or repair?", "followUp": "What would it look like to make repair your first instinct?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-5', 'Communication and Emotional Safety', 'Learn how to talk in ways that lower defensiveness and make hard conversations usable.', 'Learn how to talk in ways that lower defensiveness and make hard conversations usable.', '12 min', 5, ARRAY['Gottman Method', 'Emotionally Focused Therapy']::text[], '{"introduction": "Good communication is not just about saying more. It is about making it easier for your partner to hear what you mean.\n\nWhen people feel emotionally safe, they can be more honest, more open, and less reactive.", "sections": [{"title": "Speak to regulate, not to win", "body": "In stressed relationships, people often use communication to prove a point or protect themselves. That usually backfires. The more useful goal is regulation: helping both people stay in the conversation long enough to understand what is happening.\n\nClear communication lowers threat when it is direct, kind, and not overloaded with assumptions."}, {"title": "Validation before solutions", "body": "Many fights are not solved because one partner jumps to advice before the other feels understood. Validation does not mean agreement. It means showing the other person that their experience makes sense to you.\n\nThat small move often opens the door to actual problem-solving.", "tip": {"title": "Validation first", "steps": ["Reflect what you heard", "Name the emotion you think they feel", "Ask if you understood correctly", "Only then offer a solution"]}}, {"title": "Pausing well is part of communication", "body": "Some conversations need a timeout, not because the relationship is bad, but because the nervous system is overloaded.\n\nA good pause has a return plan. Otherwise it just becomes avoidance in disguise."}], "conclusion": "Communication gets better when both people feel less attacked, more seen, and more able to return to the conversation later if needed."}'::jsonb, '["The goal of communication is clarity and safety", "Validation helps people stay open", "Pauses work best when they include a return time", "Talking less defensively often helps more than talking more"]'::jsonb, '[{"title": "Reflect Before Responding", "description": "Practice a single conversation pattern that reduces defensiveness.", "duration": "10 min", "instructions": ["Choose one recent disagreement", "Rewrite your response as a reflection first", "Add one question that invites clarity", "Compare how it feels to your original response"]}]'::jsonb, '{"question": "What usually makes you feel unheard in conversation?", "followUp": "What would help you stay open instead of getting defensive?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-6', 'Trust and Vulnerability', 'Understand how trust is built through predictability, honesty, and safe disclosure.', 'Understand how trust is built through predictability, honesty, and safe disclosure.', '11 min', 6, ARRAY['Gottman Method']::text[], '{"introduction": "Trust is not just a feeling. It is a pattern of evidence.\n\nPeople trust when actions are predictable, promises are kept, and vulnerability is handled with care.", "sections": [{"title": "Trust grows from small deposits", "body": "The relationship does not need one huge breakthrough to build trust. It needs many small moments that prove a partner can be counted on.\n\nConsistency, follow-through, and honesty matter because they make the future feel less uncertain."}, {"title": "Vulnerability should be paced", "body": "Being open too quickly can feel risky, but being closed forever can make the relationship shallow. Healthy vulnerability is paced and mutual.\n\nYou reveal enough to be real, and you pay attention to whether the relationship responds with care.", "example": {"scenario": "One partner wants to share a fear, but is unsure whether it will be received gently.", "analysis": "Trust increases when disclosure is met with protection rather than dismissal."}}, {"title": "After a rupture, trust needs repair plus proof", "body": "An apology helps, but trust also needs repeated proof that the behavior changed. Words matter, but behavior is what the nervous system remembers.\n\nIf trust was shaken, do not rely on one conversation. Use consistency.", "tip": {"title": "Trust rebuild steps", "steps": ["Name what happened without minimizing it", "Say what will be different next time", "Follow through on a concrete promise", "Let the pattern prove itself over time"]}}], "conclusion": "Trust and vulnerability work together: trust makes disclosure possible, and vulnerability gives trust something real to respond to."}'::jsonb, '["Trust is built through predictable behavior", "Vulnerability should be mutual and paced", "Repair after rupture needs proof, not just apology", "Safety is a pattern the body learns over time"]'::jsonb, '[{"title": "Trust Audit", "description": "Identify where trust is strong and where it needs more evidence.", "duration": "15 min", "instructions": ["Name one area where your partner is reliable", "Name one area where trust feels shaky", "Choose one concrete behavior that would help", "Discuss how you will measure progress"]}]'::jsonb, '{"question": "What helps you feel safe enough to be vulnerable?", "followUp": "What can your partner do that makes trust easier to offer?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-7', 'Intimacy and Closeness', 'Explore emotional, physical, intellectual, and shared-time intimacy.', 'Explore emotional, physical, intellectual, and shared-time intimacy.', '13 min', 7, ARRAY['Intimacy process research']::text[], '{"introduction": "Intimacy is broader than sex. It is the experience of being known, chosen, and emotionally near.\n\nCouples often struggle when they only track one kind of closeness and ignore the others.", "sections": [{"title": "Closeness has multiple forms", "body": "Some couples connect best through conversation. Others through touch, shared activities, playful energy, or quiet presence.\n\nThe real question is not which form is best. It is which forms help each of you feel most alive and connected."}, {"title": "Desire and safety both matter", "body": "People often want closeness and safety at the same time, but stress can make those needs feel in conflict. Intimacy improves when partners can name what helps them feel relaxed and what makes them shut down.\n\nThat honesty turns guesswork into collaboration.", "example": {"scenario": "One partner wants more affection, while the other feels pressure and pulls back.", "analysis": "The solution is not forcing more contact. It is finding a pace that increases safety for both people."}}, {"title": "Rituals create closeness on purpose", "body": "Rituals are small repeated moments that remind each person that they matter. They can be a good morning check-in, a walk after dinner, a kiss goodbye, or a weekly sit-down.\n\nCloseness gets easier when it is built into the rhythm of the relationship.", "tip": {"title": "Create one ritual", "steps": ["Pick one daily or weekly moment", "Make it short and repeatable", "Keep it low-pressure", "Protect it even when life gets busy"]}}], "conclusion": "Intimacy deepens when partners understand the forms of closeness each person needs and build rituals that support them."}'::jsonb, '["Intimacy includes emotional, physical, intellectual, and shared-time closeness", "Safety and desire both matter", "Rituals help intimacy become reliable", "The best closeness is felt, not forced"]'::jsonb, '[{"title": "Intimacy Map", "description": "Identify your preferred forms of closeness and one way to strengthen each.", "duration": "15 min", "instructions": ["Write the top 2 forms of closeness that matter most to you", "Ask your partner to do the same", "Choose one small action for each form", "Try it for one week"]}]'::jsonb, '{"question": "What kind of closeness do you want more of right now?", "followUp": "What makes closeness feel easier instead of pressured?"}'::jsonb, 'draft'),
  ('relationship-foundations', 'rf-8', 'Shared Meaning and Values', 'Build direction, purpose, and shared identity as a couple.', 'Build direction, purpose, and shared identity as a couple.', '12 min', 8, ARRAY['Gottman Method']::text[], '{"introduction": "Shared meaning is the sense that your relationship stands for something. It is the feeling that your day-to-day life fits into a bigger picture.\n\nCouples without shared meaning can still love each other, but they may feel less grounded when life gets hard.", "sections": [{"title": "Rituals and roles shape meaning", "body": "The story of the relationship lives in routines, traditions, and the responsibilities you each carry. Even small rituals can create a feeling of \"us.\"\n\nMeaning grows when both partners feel like co-authors instead of passengers."}, {"title": "Values conflict is normal", "body": "No two people match perfectly. The goal is not identical values. It is enough alignment to make decisions without constant friction.\n\nHealthy couples can name what matters most, where they differ, and how they will navigate the gap respectfully."}, {"title": "A shared future needs a shared picture", "body": "When couples can describe the kind of life they want together, they tend to make better decisions in the present.\n\nA shared future does not need to be dramatic. It just needs to feel believable and mutual.", "tip": {"title": "Shared meaning conversation", "steps": ["Describe what kind of couple you want to be", "Name one tradition you want to protect", "Pick one value that should guide big decisions", "Write one sentence about your shared future"]}}], "conclusion": "Shared meaning makes love feel directional. It turns connection into a life the two of you are intentionally building."}'::jsonb, '["Shared meaning gives the relationship direction", "Values alignment is about workable overlap, not sameness", "Rituals and roles help create a sense of \"us\"", "A shared future makes decisions easier"]'::jsonb, '[{"title": "Meaning Statement", "description": "Write a short statement about what your relationship stands for.", "duration": "15 min", "instructions": ["Finish the sentence: \"Our relationship is about...\"", "Share your version with your partner", "Find one phrase you both like", "Keep it somewhere visible"]}]'::jsonb, '{"question": "What do you want your relationship to stand for over time?", "followUp": "What shared tradition or value would make that feel more real?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Connection (6 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('connection-series', 'Connection', 'The everyday habits that help partners feel close, responsive, and emotionally present.', 'Closeness is built in small, ordinary moments far more than in grand gestures. This series looks at how couples notice each other, stay curious, celebrate together, and find their way back after drifting apart.', '✨', 2, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('connection-series', 'daily-moments', 'Small Moments, Big Difference', 'How noticing and responding to everyday bids for attention builds a lasting connection.', 'How noticing and responding to everyday bids for attention builds a lasting connection.', '7 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "Most of what keeps a relationship warm happens in moments that barely register: a comment about the news, a sigh at the end of the day, a \"look at this.\" Each of these is a small reach toward your partner. How those reaches are met, over and over, shapes how connected you both feel.", "sections": [{"title": "What a bid looks like", "body": "A bid is any attempt to get your partner''s attention, interest, or support. It can be obvious (\"Can we talk?\") or subtle (reading a headline out loud, a hand on the shoulder, a joke). There are three broad ways to respond: turning toward (engaging, even briefly), turning away (not noticing or ignoring), and turning against (responding with irritation).\n\nTurning toward does not require a big response. \"Huh, really?\" or a smile counts. What matters is that the reach lands somewhere.", "research": {"text": "In a study of newlywed couples, partners who stayed together turned toward each other''s everyday bids far more often than couples who later separated, and those small responses also predicted more humor and affection during conflict.", "source": "Driver & Gottman, Family Process", "year": 2004}}, {"title": "Why small responses add up", "body": "Each response is like a deposit into a shared account of goodwill. When the account is full, a tired or clumsy moment is read generously (\"they''re stressed\"). When it runs low, the same moment feels like proof of not mattering.\n\nMissed bids are normal. Everyone misses some. The pattern over weeks matters much more than any single moment.", "example": {"scenario": "One partner says, \"Wow, look at that sunset,\" while the other is scrolling their phone.", "dialogue": "Turning away: no reply. Turning toward: \"Oh, that''s beautiful — the colors are wild tonight.\"", "analysis": "The second response takes three seconds, but it tells your partner their small moment was worth your attention."}}, {"title": "Getting better at noticing", "body": "Many bids are missed not from lack of care but from distraction or not recognizing them as bids. Learning your partner''s typical ways of reaching out helps. Some people reach with words, others with touch, humor, or small acts.", "tip": {"title": "Practice turning toward", "steps": ["For one week, each notice three bids a day from your partner.", "Respond to each with at least a small sign of interest.", "At the end of the week, share which moments felt most noticed."]}}], "conclusion": "Connection isn''t something you schedule once and then have. It''s woven from hundreds of tiny responses. The encouraging part is that each one is easy — and each one counts."}'::jsonb, '["A bid is any small reach for attention, interest, or support", "Turning toward can be as simple as a word or a glance", "The pattern over time matters more than any single missed moment", "Learning how your partner reaches out makes bids easier to notice"]'::jsonb, '[{"title": "Bid spotting", "description": "Get curious about how each of you reaches out.", "duration": "10 min", "instructions": ["Each list three ways you tend to reach for your partner''s attention.", "Share your lists and guess which ones your partner notices most easily.", "Name one kind of bid you''d like noticed more often, and how you''d like it met."]}]'::jsonb, '{"question": "When do you feel most noticed by your partner in an ordinary day?", "followUp": "What is one small way you could make that moment happen more often?"}'::jsonb, 'draft'),
  ('connection-series', 'love-maps', 'Knowing Each Other''s Inner World', 'Staying curious about your partner''s hopes, worries, and daily life as both of you change.', 'Staying curious about your partner''s hopes, worries, and daily life as both of you change.', '7 min', 2, ARRAY['Gottman Method']::text[], '{"introduction": "Early on, couples ask each other endless questions. Over time, many stop — not from lack of interest, but because they assume they already know. Yet people keep changing: new stresses, new dreams, new friendships, new worries. Staying curious keeps your picture of each other current.", "sections": [{"title": "What a love map is", "body": "A \"love map\" is the mental picture you hold of your partner''s world: their current stresses, their friends and rivals, what they''re looking forward to, their fears, and what they''d love to do someday. Couples with detailed, up-to-date love maps tend to weather big changes, like a new baby or a job loss, with more steadiness.", "research": {"text": "In Gottman''s research, couples who knew each other''s worlds in detail were better able to handle stressful life events without losing closeness.", "source": "Gottman & Silver, The Seven Principles for Making Marriage Work", "year": 1999}}, {"title": "Open questions keep the map current", "body": "Closed questions (\"Good day?\") get one-word answers. Open questions invite a story: \"What was the most interesting part of your day?\" \"What''s been on your mind lately?\" \"What would you do with a free month?\"\n\nThe goal isn''t to interview each other, but to keep discovering. Listen for details you didn''t know and follow them.", "tip": {"title": "Questions worth asking", "steps": ["What''s something you''re looking forward to right now?", "Who''s been easy — or hard — to deal with lately?", "What''s a dream you haven''t mentioned in a while?", "What would make next week feel good for you?"]}}], "conclusion": "Knowing your partner is not a one-time achievement. It''s an ongoing, curious conversation — and one of the quiet foundations of friendship in a relationship."}'::jsonb, '["A love map is your picture of your partner''s current inner world", "People keep changing, so the map needs regular updating", "Open questions invite stories instead of one-word answers", "Curiosity is a form of care"]'::jsonb, '[{"title": "Update your love maps", "description": "Ask and answer open questions about each other''s current world.", "duration": "15 min", "instructions": ["Take turns asking each other three open questions from the list above, or your own.", "The listener asks one follow-up question before moving on.", "Each share one thing you learned that surprised you."]}]'::jsonb, '{"question": "What is something about your partner''s life right now that you''d like to understand better?", "followUp": "When could you ask them about it this week?"}'::jsonb, 'draft'),
  ('connection-series', 'rituals', 'Rituals of Connection', 'Creating small, reliable habits that keep you connected through busy seasons.', 'Creating small, reliable habits that keep you connected through busy seasons.', '6 min', 3, ARRAY['Gottman Method', 'Family systems research']::text[], '{"introduction": "When life gets busy, connection is often the first thing to slip — not because it matters less, but because nothing protects it. Rituals are small, repeated moments you both count on: how you say goodbye in the morning, how you reconnect in the evening, how you spend Sunday mornings.", "sections": [{"title": "Why predictability helps", "body": "A ritual works because it happens without needing to be negotiated each time. It turns connection from something you hope for into something built into the week. Rituals also carry meaning: the way you celebrate, grieve, and rest together becomes part of your shared identity.", "research": {"text": "A review of five decades of research found that regular routines and meaningful rituals are linked to stronger relationships and better well-being in families.", "source": "Fiese et al., Journal of Family Psychology", "year": 2002}}, {"title": "Rituals that work in real life", "body": "Good rituals are small enough to survive a busy week: a six-second kiss before leaving, a ten-minute check-in after work with phones away, a weekly walk, a shared playlist on long drives, or a yearly tradition on your anniversary. They don''t have to be special — they have to be yours.", "tip": {"title": "Designing a ritual", "steps": ["Pick one moment in the day or week that often feels rushed or disconnected.", "Agree on one small, specific thing you''ll do together at that moment.", "Try it for two weeks, then adjust it together."]}}], "conclusion": "Rituals protect connection when life doesn''t make room for it on its own. Start with one small, repeatable moment and let it grow."}'::jsonb, '["Rituals protect connection during busy seasons", "Predictability removes the need to negotiate closeness each time", "Small and repeatable beats grand and occasional", "Rituals carry shared meaning over time"]'::jsonb, '[{"title": "Build one ritual", "description": "Design a single connection ritual you''ll both try for two weeks.", "duration": "10 min", "instructions": ["Each name the part of your day or week when you feel most disconnected.", "Choose one moment and agree on a small ritual for it.", "Set a reminder to check in on how it''s going in two weeks."]}]'::jsonb, '{"question": "What small moment together do you already look forward to?", "followUp": "How could you protect it on busy weeks?"}'::jsonb, 'draft'),
  ('connection-series', 'good-news', 'Celebrating Good News', 'How responding to each other''s wins — not just struggles — builds closeness.', 'How responding to each other''s wins — not just struggles — builds closeness.', '6 min', 4, ARRAY['Positive psychology research (capitalization)']::text[], '{"introduction": "Couples often think support means being there during hard times. It does — but how you respond when things go well matters just as much. When a partner shares good news, the response can either amplify the moment or quietly shrink it.", "sections": [{"title": "Four ways to respond to good news", "body": "Imagine your partner says, \"I got picked to lead the new project!\" Responses tend to fall into four styles:\n\n• Active-constructive: enthusiastic and curious (\"That''s fantastic! How did they tell you?\")\n• Passive-constructive: pleasant but flat (\"Nice.\")\n• Active-destructive: finds the downside (\"That''ll mean a lot more hours.\")\n• Passive-destructive: changes the subject (\"What''s for dinner?\")\n\nOnly the first one reliably makes the good moment feel bigger.", "research": {"text": "Researchers found that when partners responded to good news with enthusiasm and interest, relationships were more satisfying and more trusting — and this mattered even more than how they responded to bad news.", "source": "Gable, Reis, Impett & Asher, Journal of Personality and Social Psychology", "year": 2004}}, {"title": "Making it a habit", "body": "Active-constructive responding is a skill, not a personality trait. It usually means asking questions, reflecting the other person''s feeling, and letting the moment last a little longer before moving on. Concerns can wait for another conversation.", "tip": {"title": "Next time your partner shares good news", "steps": ["Pause what you''re doing and turn toward them.", "Ask a question about the details or how it felt.", "Name the feeling: \"You must be so proud.\""]}}], "conclusion": "Celebrating each other''s wins is one of the simplest ways to feel on the same team. Good news shared well becomes good news doubled."}'::jsonb, '["How you respond to good news shapes trust and closeness", "Enthusiasm and curiosity make good moments bigger", "Concerns can wait for a separate conversation", "This is a skill you can practice"]'::jsonb, '[{"title": "Share a recent win", "description": "Practice responding to each other''s good news.", "duration": "10 min", "instructions": ["Each share one good thing from the past week, however small.", "The listener responds with enthusiasm and at least two questions.", "Switch roles, then share how it felt to be celebrated."]}]'::jsonb, '{"question": "How does your partner usually react when you share good news?", "followUp": "What kind of response makes you feel most celebrated?"}'::jsonb, 'draft'),
  ('connection-series', 'novelty-play', 'Play and New Experiences', 'Why doing new and playful things together keeps a long relationship lively.', 'Why doing new and playful things together keeps a long relationship lively.', '6 min', 5, ARRAY['Self-expansion research']::text[], '{"introduction": "Familiarity brings comfort, but it can also bring routine. Many couples find that the spark they felt early on faded not because anything went wrong, but because life settled into repeat. Doing new, mildly challenging, or playful things together can bring some of that energy back.", "sections": [{"title": "Why novelty matters", "body": "Early in a relationship, everything is new, and partners associate that sense of growth and excitement with each other. Later, shared novelty can recreate some of that feeling. The activity doesn''t need to be dramatic — trying a new hike, cooking an unfamiliar cuisine, learning a skill together, or visiting a new neighborhood all count.", "research": {"text": "In experiments, couples who took part in a novel, mildly challenging activity together reported greater relationship satisfaction afterward than couples who did something pleasant but familiar.", "source": "Aron, Norman, Aron, McKenna & Heyman, Journal of Personality and Social Psychology", "year": 2000}}, {"title": "Room to play", "body": "Play is also a way of connecting: inside jokes, teasing that''s affectionate rather than cutting, games, and silliness. Couples who can laugh together often recover from tension faster, because humor softens the moment and signals \"we''re still okay.\"", "tip": {"title": "Bringing in novelty", "steps": ["Each write down three things you''ve never done together.", "Pick one you can do in the next two weeks.", "Afterward, share one moment from it you enjoyed."]}}], "conclusion": "You don''t need to recreate the early days of your relationship. But making room for new experiences and play keeps the relationship growing instead of just maintaining."}'::jsonb, '["Shared novelty can renew a sense of excitement", "New doesn''t have to mean big or expensive", "Play and humor help couples recover from tension", "Growth together is part of what keeps closeness alive"]'::jsonb, '[{"title": "Novelty list", "description": "Build a shared list of new things to try.", "duration": "15 min", "instructions": ["Brainstorm ten new activities together, from tiny to ambitious.", "Each star the two that excite you most.", "Put one on your calendar this month."]}]'::jsonb, '{"question": "When do the two of you laugh the most together?", "followUp": "What gets in the way of more playful time right now?"}'::jsonb, 'draft'),
  ('connection-series', 'reconnecting', 'Reconnecting After Distance', 'What to do when you notice you''ve drifted apart.', 'What to do when you notice you''ve drifted apart.', '7 min', 6, ARRAY['Emotionally Focused Therapy']::text[], '{"introduction": "Almost every couple goes through stretches of feeling more like roommates than partners — during a new baby, a demanding job, a move, or simply a long, busy season. Drifting apart is common. What matters is noticing it and reaching back toward each other.", "sections": [{"title": "Distance is often protest or protection", "body": "When closeness fades, people tend to respond in one of two ways. Some reach harder — asking, pushing, or criticizing, because they miss the connection. Others pull back to avoid conflict or disappointment. Both are attempts to cope with the same underlying longing: to feel that the other person is there.\n\nSeeing distance this way can soften blame. The question becomes less \"why are you like this?\" and more \"how did we lose each other, and how do we find our way back?\"", "research": {"text": "Emotionally Focused Therapy describes how partners get caught in cycles of pursuing and withdrawing, and how naming the need for connection underneath helps couples re-engage.", "source": "Johnson, Hold Me Tight", "year": 2008}}, {"title": "Reaching back", "body": "Reconnecting usually starts with a soft, direct reach: \"I miss us. Can we find some time this week that''s just ours?\" It helps to speak about your own feeling rather than your partner''s failures, and to start small — a walk, a meal without screens, twenty minutes of real conversation.", "example": {"scenario": "After weeks of long workdays, one partner feels lonely.", "dialogue": "Instead of \"You never have time for me,\" they try: \"I''ve been missing you lately. Could we take a walk tonight, just us?\"", "analysis": "The request names the feeling and offers a clear, easy way to reconnect."}}], "conclusion": "Distance isn''t a verdict on your relationship. It''s a signal. Naming it gently and reaching back — even in small ways — is how couples find each other again."}'::jsonb, '["Drifting apart is common during demanding seasons", "Pursuing and withdrawing are both responses to missing connection", "Speaking from your own feeling invites your partner closer", "Reconnection starts small and specific"]'::jsonb, '[{"title": "Find your way back", "description": "Name how you''ve each experienced recent distance and plan one step back.", "duration": "15 min", "instructions": ["Each finish the sentence: \"Lately I''ve been missing…\"", "Listen without defending; reflect what you heard.", "Choose one small thing to do together this week."]}]'::jsonb, '{"question": "When you feel distant from your partner, do you tend to reach harder or pull back?", "followUp": "What would help you reach toward them more gently?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Communication (6 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('communication-series', 'Communication', 'How couples speak, listen, and make hard conversations easier to handle.', 'Most couples don''t need to communicate more — they need ways of talking that keep both people feeling safe and understood. This series covers starting gently, listening well, validating, asking for what you need, and handling difficult topics.', '💬', 3, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('communication-series', 'soft-startup', 'Soft Start-Up', 'Raising a concern in a way that invites your partner in instead of putting them on guard.', 'Raising a concern in a way that invites your partner in instead of putting them on guard.', '7 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "How a difficult conversation begins shapes how it goes. Conversations that open with blame or sarcasm tend to end badly, no matter how reasonable the underlying point. A gentler opening keeps your partner able to hear you.", "sections": [{"title": "Why the first minutes matter", "body": "A harsh start-up — \"You never help around here\" — usually triggers defensiveness, and the conversation becomes about defending rather than solving. A soft start-up raises the same issue in a way that''s easier to receive.", "research": {"text": "In studies of newlywed couples, the way conflict discussions started — gently or harshly — strongly predicted how the discussion went and how the relationship fared years later.", "source": "Gottman, Coan, Carrère & Swanson, Journal of Marriage and the Family", "year": 1998}}, {"title": "The shape of a soft start-up", "body": "A soft start-up usually has three parts: how you feel, about a specific situation, and what you need. It describes rather than diagnoses. \"I feel overwhelmed when the kitchen is still messy at night. Could we figure out a plan for cleaning up after dinner?\" is very different from \"You''re so lazy.\"", "example": {"scenario": "A partner is frustrated that plans keep getting cancelled.", "dialogue": "Harsh: \"You obviously don''t care about spending time with me.\" Soft: \"I felt really disappointed when our dinner got cancelled again. Can we protect one evening a week?\"", "analysis": "The soft version shares the feeling and a request without attacking character."}, "tip": {"title": "Before you raise something hard", "steps": ["Name your feeling, not your partner''s flaw.", "Describe the specific situation, not \"always\" or \"never.\"", "End with a clear, doable request."]}}], "conclusion": "Starting gently isn''t about hiding what you feel. It''s about saying it in a way that gives the conversation a real chance to go somewhere good."}'::jsonb, '["The opening of a hard conversation shapes where it goes", "Harsh openings trigger defensiveness", "Feeling + specific situation + request is a reliable structure", "Describing is easier to hear than diagnosing"]'::jsonb, '[{"title": "Rewrite the opener", "description": "Practice turning complaints into soft start-ups.", "duration": "10 min", "instructions": ["Each write down one recurring frustration in the harshest way it comes out.", "Together, rewrite each one as feeling + situation + request.", "Read the new versions aloud and notice how they land differently."]}]'::jsonb, '{"question": "How do you tend to start conversations when you''re upset?", "followUp": "What''s one phrase you could use to begin more gently?"}'::jsonb, 'draft'),
  ('communication-series', 'listening', 'Listening to Understand', 'A simple structure for making sure each partner feels heard before problem-solving begins.', 'A simple structure for making sure each partner feels heard before problem-solving begins.', '7 min', 2, ARRAY['PREP (Prevention and Relationship Education Program)']::text[], '{"introduction": "In hard conversations, most people listen in order to respond. They wait for a pause, then make their own point. The result: both people talk, and neither feels heard. Listening to understand means making sure you''ve really gotten your partner''s message before sharing your own.", "sections": [{"title": "Speaker and listener", "body": "One useful structure gives one person \"the floor\" at a time. The speaker shares their view in short chunks, using \"I\" statements. The listener paraphrases what they heard — without adding their own opinion — until the speaker agrees they got it. Then they switch.\n\nIt feels slow at first. That''s the point: slowing down prevents the escalation that happens when both people talk past each other.", "research": {"text": "The speaker–listener technique is a core part of the PREP program, whose research links structured, safe communication skills with lower rates of relationship distress.", "source": "Markman, Stanley & Blumberg, Fighting for Your Marriage", "year": 2010}}, {"title": "What good paraphrasing sounds like", "body": "Paraphrasing isn''t repeating word for word. It''s showing you understood the meaning and the feeling: \"So when I made plans without checking, you felt left out and like your time didn''t matter?\" If you get it wrong, the speaker clarifies — no harm done.", "tip": {"title": "Listener rules", "steps": ["Don''t rebut until it''s your turn.", "Paraphrase the main point and the feeling.", "Ask \"Did I get that right?\" and keep going until the answer is yes."]}}], "conclusion": "Feeling understood is often what turns a fight back into a conversation. Once both people feel heard, solutions usually come much more easily."}'::jsonb, '["Listening to respond is different from listening to understand", "One speaker at a time slows escalation down", "Paraphrase meaning and feeling, not just words", "Understanding comes before problem-solving"]'::jsonb, '[{"title": "Speaker–listener practice", "description": "Try the structure on a low-stakes topic first.", "duration": "15 min", "instructions": ["Pick a mild topic, like how to spend next weekend.", "One speaks in short chunks; the other paraphrases until the speaker says \"yes, that''s it.\"", "Switch roles, then talk about what felt different."]}]'::jsonb, '{"question": "When do you feel most listened to by your partner?", "followUp": "What could they do to help you feel heard in harder moments?"}'::jsonb, 'draft'),
  ('communication-series', 'validation', 'Validation Without Agreement', 'How acknowledging your partner''s feelings calms conflict — even when you see things differently.', 'How acknowledging your partner''s feelings calms conflict — even when you see things differently.', '6 min', 3, ARRAY['Dialectical and couple communication research']::text[], '{"introduction": "Many people hold back validation because they think it means agreeing. It doesn''t. Validation means communicating that your partner''s feelings make sense from where they stand — even if you remember things differently or want a different outcome.", "sections": [{"title": "Why validation calms things down", "body": "When people feel dismissed (\"You''re overreacting\"), their emotions tend to escalate, because now they''re fighting to be taken seriously. When they feel understood (\"I can see why that hurt\"), the intensity usually drops, and it becomes possible to talk about solutions.", "research": {"text": "In laboratory research, validating responses reduced people''s emotional arousal during difficult conversations, while invalidating responses increased it.", "source": "Shenk & Fruzzetti, Journal of Social and Clinical Psychology", "year": 2011}}, {"title": "Phrases that validate", "body": "Validation can be as simple as: \"That makes sense.\" \"I can see why you''d feel that way.\" \"Given what happened, of course you''re frustrated.\" Then, if needed, you can add your own perspective: \"…and I see it a little differently. Can I share how it looked from my side?\"", "tip": {"title": "Validate first", "steps": ["Name the feeling you hear.", "Say what makes it understandable.", "Only then add your own view, with \"and,\" not \"but.\""]}}], "conclusion": "Validation isn''t surrender. It''s the bridge that lets two different perspectives meet without either person feeling erased."}'::jsonb, '["Validation means \"your feelings make sense,\" not \"you''re right\"", "Feeling dismissed escalates emotions; feeling understood calms them", "You can validate and still share your own view", "\"And\" keeps both perspectives in the room"]'::jsonb, '[{"title": "Validation practice", "description": "Practice validating before responding.", "duration": "10 min", "instructions": ["One partner shares a recent frustration (not about the other partner).", "The other responds only with validation for two minutes.", "Switch, then discuss what it felt like to be validated."]}]'::jsonb, '{"question": "Is there a feeling of yours you wish your partner understood better?", "followUp": "What words would help you feel validated about it?"}'::jsonb, 'draft'),
  ('communication-series', 'needs-requests', 'Needs and Clear Requests', 'Turning complaints into needs and doable requests your partner can actually say yes to.', 'Turning complaints into needs and doable requests your partner can actually say yes to.', '7 min', 4, ARRAY['Nonviolent Communication (Rosenberg)']::text[], '{"introduction": "Under almost every complaint is an unmet need. \"You''re always on your phone\" may really mean \"I need to feel you''re with me.\" When needs stay hidden, partners argue about behavior; when needs are named, partners can work on meeting them.", "sections": [{"title": "Observations, feelings, needs, requests", "body": "Nonviolent Communication offers a four-part structure: an observation (what happened, without judgment), a feeling, the need behind the feeling, and a specific request. \"When we ate dinner with the TV on (observation), I felt lonely (feeling), because I need some time where we really talk (need). Could we have dinner without screens twice a week? (request)\"", "research": {"text": "Nonviolent Communication describes how separating observations from judgments and naming needs directly makes it easier for others to respond with care rather than defensiveness.", "source": "Rosenberg, Nonviolent Communication: A Language of Life", "year": 2003}}, {"title": "What makes a request doable", "body": "Good requests are specific, positive (what you want, not what you don''t), and truly requests — meaning \"no\" is an acceptable answer that leads to more conversation, not punishment. \"Be more supportive\" is vague; \"Could you ask me how the interview went tonight?\" is doable.", "tip": {"title": "Turning a complaint into a request", "steps": ["Name the observation without \"always\" or \"never.\"", "Ask yourself: what need is this about?", "Make a specific, doable request for this week."]}}], "conclusion": "Your partner can''t meet a need they can''t see. Naming needs and asking clearly turns frustration into something the two of you can work on together."}'::jsonb, '["Most complaints hide an unmet need", "Observation, feeling, need, request is a clear structure", "Specific, positive requests are easier to say yes to", "A real request leaves room for \"no\""]'::jsonb, '[{"title": "Complaint to request", "description": "Translate recurring complaints into needs and requests.", "duration": "15 min", "instructions": ["Each pick one recurring complaint.", "Write the need underneath it and one specific request.", "Share them and agree on one request to try this week."]}]'::jsonb, '{"question": "What need of yours tends to go unspoken?", "followUp": "How could you ask for it more directly?"}'::jsonb, 'draft'),
  ('communication-series', 'meta-emotions', 'How Each of You Feels About Feelings', 'Understanding the different ways you learned to handle emotions — and how that shapes your conversations.', 'Understanding the different ways you learned to handle emotions — and how that shapes your conversations.', '7 min', 5, ARRAY['Gottman Method (meta-emotion research)']::text[], '{"introduction": "Some people grew up in homes where emotions were talked about openly. Others learned that feelings like sadness or anger should be kept private or pushed through. These lessons shape how each of you reacts when the other gets emotional — often without either of you realizing it.", "sections": [{"title": "What meta-emotion means", "body": "\"Meta-emotion\" is how you feel about feelings. One partner may see crying as healthy release; the other may feel alarmed or helpless when tears come. One may want to talk anger through right away; the other may need space first. Neither is wrong, but mismatched styles can cause conflict about the conflict.", "research": {"text": "Research on meta-emotion found that people''s attitudes toward emotion — whether they explore it or try to shut it down — shape how families and couples respond to each other''s feelings.", "source": "Gottman, Katz & Hooven, Meta-Emotion: How Families Communicate Emotionally", "year": 1996}}, {"title": "Talking about your emotional histories", "body": "Understanding where your styles came from builds compassion. \"In my family, being upset meant you were being dramatic\" explains a lot about why someone might go quiet. Once named, you can agree on what each of you needs when feelings run high.", "tip": {"title": "Questions to explore together", "steps": ["How was anger handled in your family growing up?", "What happened when someone was sad?", "What do you need from me when you''re upset?"]}}], "conclusion": "You don''t have to share the same emotional style. But understanding each other''s styles turns \"why are you reacting like that?\" into \"I understand what you need.\""}'::jsonb, '["Meta-emotion is how you feel about feelings", "Emotional styles often come from family history", "Mismatched styles cause conflict about conflict", "Knowing what each of you needs makes hard moments easier"]'::jsonb, '[{"title": "Emotional history interview", "description": "Learn how each of you learned to handle feelings.", "duration": "20 min", "instructions": ["Take turns answering the three questions above.", "The listener asks one follow-up question for each answer.", "Each finish the sentence: \"When I''m upset, what helps most is…\""]}]'::jsonb, '{"question": "What did you learn growing up about showing emotion?", "followUp": "Which of those lessons still helps you, and which would you like to change?"}'::jsonb, 'draft'),
  ('communication-series', 'hard-topics', 'Talking About Hard Topics', 'Timing, structure, and agreements that make difficult conversations safer.', 'Timing, structure, and agreements that make difficult conversations safer.', '7 min', 6, ARRAY['PREP (Prevention and Relationship Education Program)']::text[], '{"introduction": "Some topics are hard no matter how skilled you are: money, family, sex, the future. These conversations go better when you choose the right moment, agree on some ground rules, and give yourselves permission to pause.", "sections": [{"title": "Timing and ground rules", "body": "Hard topics rarely go well when either person is exhausted, hungry, rushed, or already upset about something else. Many couples find it helps to schedule these conversations (\"Can we talk about the budget on Sunday afternoon?\") and agree on a few rules: one topic at a time, no name-calling, and either person can call a pause.", "research": {"text": "Research on commitment and communication links couples'' ability to manage conflict constructively — including agreed-upon ways to pause and return — with long-term relationship quality.", "source": "Stanley, Markman & Whitton, Family Process", "year": 2002}}, {"title": "Problem discussion vs. problem solving", "body": "Many conversations stall because couples try to solve a problem before they understand it. Separate the two: first, each person shares and feels understood. Only then brainstorm solutions together, without shooting ideas down, and pick one to try for a set time.", "tip": {"title": "A simple structure", "steps": ["Agree on the topic and a time.", "Each share your view until the other can paraphrase it.", "Brainstorm options, choose one to try, and set a check-in date."]}}], "conclusion": "Hard topics don''t get easier by avoiding them. With the right timing and a little structure, they become conversations you can have — and come back to — without damage."}'::jsonb, '["Timing matters for hard conversations", "Ground rules and permission to pause create safety", "Understand the problem before solving it", "Try a solution for a set time, then check in"]'::jsonb, '[{"title": "Your ground rules", "description": "Agree on how you''ll handle hard conversations.", "duration": "15 min", "instructions": ["Each suggest two ground rules that would help you feel safe.", "Agree on a word or signal either of you can use to pause.", "Pick one hard topic to schedule, using your new rules."]}]'::jsonb, '{"question": "Which topic do the two of you tend to avoid?", "followUp": "What would make it feel safer to talk about?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Conflict & Repair (6 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('conflict-repair-series', 'Conflict & Repair', 'How disagreement stays workable when repair happens early and respectfully.', 'Conflict is a normal part of every close relationship. What matters is how it''s handled: whether partners can stay respectful, take breaks when overwhelmed, repair quickly, and live peacefully with differences that won''t fully go away.', '🔧', 4, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('conflict-repair-series', 'perpetual-problems', 'Solvable and Perpetual Problems', 'Why many disagreements never fully go away — and how to live with them well.', 'Why many disagreements never fully go away — and how to live with them well.', '7 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "Many couples believe that a healthy relationship means solving every disagreement. In reality, most couples have some differences that come up again and again for years — about tidiness, socializing, money, or how to spend free time. These aren''t signs of failure. They''re part of being two different people.", "sections": [{"title": "Two kinds of problems", "body": "Solvable problems are situational: who picks up the kids on Tuesdays, where to go on vacation. They can be settled with compromise. Perpetual problems come from lasting differences in personality or values — one of you is more spontaneous, the other a planner. These rarely disappear. The goal with them is not to win but to keep talking about them with humor and respect.", "research": {"text": "Gottman''s research found that the majority of recurring relationship conflicts — about two thirds — are perpetual problems rooted in lasting differences rather than solvable situations.", "source": "Gottman & Silver, The Seven Principles for Making Marriage Work", "year": 1999}}, {"title": "From gridlock to dialogue", "body": "A perpetual problem becomes painful when it''s gridlocked: every conversation goes the same way and leaves both people hurt. Gridlock often hides deeper dreams or values. The partner who wants to save every dollar may be carrying a dream of security; the one who wants to spend on travel may be honoring a dream of adventure. Understanding the dream behind each position opens room to move.", "tip": {"title": "Exploring the dream behind a position", "steps": ["Ask: what does this mean to you?", "Ask: is there a story or history behind it?", "Ask: what would your ideal look like, and what''s the deeper hope in it?"]}}], "conclusion": "You don''t have to solve every disagreement. Being able to talk about lasting differences with curiosity and good humor is a sign of a strong relationship, not a weak one."}'::jsonb, '["Most recurring conflicts are perpetual, not solvable", "Perpetual problems come from lasting differences in personality or values", "The goal is ongoing dialogue, not winning", "Gridlock usually hides deeper dreams on both sides"]'::jsonb, '[{"title": "Name your perpetual problems", "description": "Sort your recurring disagreements and explore one together.", "duration": "20 min", "instructions": ["Together, list three disagreements that keep coming back.", "Mark each as solvable or perpetual.", "Pick one perpetual problem and each share the dream or value behind your position."]}]'::jsonb, '{"question": "Which recurring disagreement between you feels most stuck?", "followUp": "What might your partner''s position mean to them at a deeper level?"}'::jsonb, 'draft'),
  ('conflict-repair-series', 'flooding', 'Flooding and Taking a Break', 'Recognizing when you''re too overwhelmed to talk productively, and how to pause well.', 'Recognizing when you''re too overwhelmed to talk productively, and how to pause well.', '7 min', 2, ARRAY['Gottman Method']::text[], '{"introduction": "Sometimes an argument crosses a line where productive talking stops being possible. Your heart races, your thinking narrows, and you either want to escape or to win at any cost. This state is called flooding, and no one communicates well while in it.\n\nThese tools are for couples who feel safe with each other. If you are afraid of your partner, or conflict involves threats, intimidation, or physical harm, relationship exercises are not the right tool. In the US you can reach the National Domestic Violence Hotline at 1-800-799-7233 (or text START to 88788).", "sections": [{"title": "What happens when you''re flooded", "body": "Flooding is a physical stress response. When it kicks in, it becomes much harder to listen, take in new information, or remember why you care about the other person. People who are flooded tend to attack or shut down — not because they''re bad partners, but because their body is in fight-or-flight mode.", "research": {"text": "Gottman''s research linked physiological arousal during conflict — like elevated heart rate — with more negative interactions, and found that taking a break to calm down helped couples return to more productive conversations.", "source": "Gottman, What Predicts Divorce?", "year": 1994}}, {"title": "How to take a good break", "body": "A good break is not storming out or giving the silent treatment. It''s an agreed pause: \"I''m getting overwhelmed. I need twenty minutes, and then I want to come back to this.\" During the break, do something calming — walk, breathe slowly, listen to music — rather than rehearsing your arguments. Then come back as promised.", "tip": {"title": "Your break agreement", "steps": ["Agree on a phrase or signal that means \"I need a pause.\"", "Take at least 20 minutes to let your body calm down.", "Always name when you''ll return, and keep that promise."]}}], "conclusion": "Pausing when overwhelmed isn''t avoiding the conversation. It''s protecting it, so you can come back able to listen and be heard."}'::jsonb, '["Flooding is a physical stress response that blocks good communication", "Flooded people tend to attack or shut down", "A good break is agreed, calming, and time-limited", "Returning to the conversation keeps the break from feeling like abandonment"]'::jsonb, '[{"title": "Make a break plan", "description": "Agree ahead of time on how you''ll pause during conflict.", "duration": "10 min", "instructions": ["Each describe the early signs that you''re getting overwhelmed.", "Choose a pause phrase you both agree to honor.", "Each name one calming thing you''ll do during a break."]}]'::jsonb, '{"question": "What are your early warning signs of getting overwhelmed in an argument?", "followUp": "What helps you calm down before returning to a hard conversation?"}'::jsonb, 'draft'),
  ('conflict-repair-series', 'repair-attempts', 'Repair Attempts', 'The small words and gestures that keep an argument from spiraling.', 'The small words and gestures that keep an argument from spiraling.', '6 min', 3, ARRAY['Gottman Method']::text[], '{"introduction": "Every couple says things they regret during conflict. What distinguishes couples who do well is not the absence of mistakes but how quickly they repair — through a joke, an apology, a touch, or a simple \"can we start over?\"", "sections": [{"title": "What a repair attempt is", "body": "A repair attempt is any statement or action that de-escalates tension: \"Okay, I''m getting defensive.\" \"Let me try that again.\" \"I love you, I''m just really frustrated.\" \"Can we take a break?\" Repairs don''t have to be elegant. What matters is that they''re offered — and accepted.", "research": {"text": "Gottman described successful repair attempts as a key factor distinguishing couples who stay happy from those who don''t, even when both kinds of couples have similar amounts of conflict.", "source": "Gottman & Silver, The Seven Principles for Making Marriage Work", "year": 1999}}, {"title": "Receiving repair", "body": "Repair only works if it''s received. When your partner reaches out mid-argument — even clumsily — try to meet them: \"Thank you, I want to start over too.\" Rejecting a repair (\"Don''t try to change the subject\") tends to escalate things further.", "tip": {"title": "Repair phrases to keep handy", "steps": ["\"I''m feeling defensive. Can you say that again?\"", "\"You''re right about that part.\"", "\"Let me try that again, more gently.\"", "\"We''re on the same team here.\""]}}], "conclusion": "Repair is one of the most powerful skills a couple can build. Offering it early and accepting it generously keeps conflict from causing lasting damage."}'::jsonb, '["Repair attempts de-escalate tension during conflict", "They don''t need to be elegant to work", "Accepting repair matters as much as offering it", "Having go-to phrases makes repair easier in the moment"]'::jsonb, '[{"title": "Your repair toolkit", "description": "Choose repair phrases that feel natural for the two of you.", "duration": "10 min", "instructions": ["Read the repair phrases above together.", "Each pick two that you''d find easiest to say — and to hear.", "Agree to try one the next time a disagreement starts heating up."]}]'::jsonb, '{"question": "What helps you soften during an argument?", "followUp": "How could your partner offer repair in a way you''d find easy to accept?"}'::jsonb, 'draft'),
  ('conflict-repair-series', 'four-horsemen', 'The Four Horsemen and Their Antidotes', 'Four patterns that damage relationships during conflict, and what to do instead.', 'Four patterns that damage relationships during conflict, and what to do instead.', '8 min', 4, ARRAY['Gottman Method']::text[], '{"introduction": "Some ways of fighting are especially corrosive over time. Gottman called them the \"Four Horsemen\": criticism, contempt, defensiveness, and stonewalling. Everyone slips into them sometimes. The goal is to recognize them and reach for their antidotes.\n\nThese tools are for couples who feel safe with each other. If you are afraid of your partner, or conflict involves threats, intimidation, or physical harm, relationship exercises are not the right tool. In the US you can reach the National Domestic Violence Hotline at 1-800-799-7233 (or text START to 88788).", "sections": [{"title": "The four patterns", "body": "• Criticism attacks character instead of describing a behavior (\"You''re so selfish\").\n• Contempt expresses disgust or superiority — mockery, eye-rolling, sarcasm. It is the most damaging of the four.\n• Defensiveness deflects responsibility (\"Well, you do it too\").\n• Stonewalling shuts down and withdraws from the conversation, often when flooded.", "research": {"text": "Gottman''s longitudinal research found that these four patterns during conflict — especially contempt — were strong predictors of later relationship breakdown.", "source": "Gottman, What Predicts Divorce?", "year": 1994}}, {"title": "The antidotes", "body": "Each pattern has a counter-move:\n• Instead of criticism: a gentle start-up that describes the situation and your feeling.\n• Instead of contempt: build a culture of appreciation and respect, and express your own needs rather than judgment.\n• Instead of defensiveness: take responsibility for your part, even a small part.\n• Instead of stonewalling: notice you''re flooded, ask for a break, and come back.", "tip": {"title": "Catching a horseman in the moment", "steps": ["Notice the pattern without shaming yourself for it.", "Name it gently: \"I think I just got defensive.\"", "Try the antidote, even imperfectly."]}}], "conclusion": "The Four Horsemen describe patterns, not people. Every couple uses them sometimes. Learning to spot them — especially in yourself — and reaching for the antidote is what keeps conflict from wearing the relationship down."}'::jsonb, '["Criticism, contempt, defensiveness, and stonewalling damage relationships over time", "Contempt is the most corrosive of the four", "Each pattern has a specific antidote", "Noticing your own patterns matters more than pointing out your partner''s"]'::jsonb, '[{"title": "Horsemen and antidotes", "description": "Reflect on your own patterns without blaming each other.", "duration": "15 min", "instructions": ["Each privately pick the horseman you slip into most often.", "Share it with your partner — only about yourself.", "Each name the antidote you''ll practice and how your partner can support you."]}]'::jsonb, '{"question": "Which of the four patterns do you notice in yourself most often?", "followUp": "What makes it more likely to show up, and what helps you catch it?"}'::jsonb, 'draft'),
  ('conflict-repair-series', 'accepting-influence', 'Accepting Influence and Finding Compromise', 'Letting your partner''s view change your mind — and building compromises you both can live with.', 'Letting your partner''s view change your mind — and building compromises you both can live with.', '7 min', 5, ARRAY['Gottman Method']::text[], '{"introduction": "Compromise sounds simple, but it''s hard when both people feel strongly. A key ingredient is being genuinely open to your partner''s perspective — letting their needs and opinions actually shape decisions.", "sections": [{"title": "Accepting influence", "body": "Accepting influence means treating your partner''s view as legitimate and letting it affect what you do. It doesn''t mean giving in on everything. It means decisions are made together rather than by one person defending their position.", "research": {"text": "Research on newlywed couples found that partners'' willingness to accept influence from each other predicted more stable, satisfying relationships.", "source": "Gottman, Coan, Carrère & Swanson, Journal of Marriage and the Family", "year": 1998}}, {"title": "Finding flexible middle ground", "body": "One practical approach: each partner identifies their core needs — the few things they can''t give up — and the areas where they can be flexible. Compromise then happens in the flexible zone, while both people''s core needs are protected.", "tip": {"title": "The core and flexible circles", "steps": ["Each write your non-negotiable core needs on this issue (keep it short).", "Each write the areas where you''re flexible.", "Build a plan that protects both cores and uses the flexible areas."]}}], "conclusion": "Good compromise isn''t about each person losing half. It''s about protecting what matters most to both of you and being generous everywhere else."}'::jsonb, '["Accepting influence means your partner''s view genuinely shapes decisions", "It doesn''t mean giving in on everything", "Separating core needs from flexible areas makes compromise easier", "Good compromises protect what matters most to both people"]'::jsonb, '[{"title": "Core and flexible", "description": "Use the two-circle method on a current decision.", "duration": "20 min", "instructions": ["Pick a real decision you''re working through together.", "Each fill in your core needs and flexible areas.", "Together, draft one plan that honors both sets of core needs."]}]'::jsonb, '{"question": "When has your partner''s perspective changed your mind in a good way?", "followUp": "What makes it easier for you to be open to their view?"}'::jsonb, 'draft'),
  ('conflict-repair-series', 'forgiveness', 'Forgiveness and Moving Forward', 'What forgiveness is — and isn''t — and how couples let go of past hurts.', 'What forgiveness is — and isn''t — and how couples let go of past hurts.', '7 min', 6, ARRAY['Forgiveness research']::text[], '{"introduction": "Over time, every couple accumulates hurts: careless words, missed moments, broken promises. Some fade on their own. Others linger and get brought up again and again. Forgiveness is how couples keep past hurts from shaping the present.", "sections": [{"title": "What forgiveness is", "body": "Forgiveness is a gradual process of letting go of resentment and the wish to punish, while still acknowledging that something hurtful happened. It is not pretending the hurt didn''t matter, and it doesn''t require forgetting. It also doesn''t mean accepting ongoing harm.", "research": {"text": "Research with married couples found that forgiveness was associated with better conflict resolution, and that couples who forgave more tended to handle disagreements more constructively.", "source": "Fincham, Beach & Davila, Journal of Family Psychology", "year": 2004}}, {"title": "Helping forgiveness along", "body": "Forgiveness usually comes more easily when the partner who caused hurt acknowledges it specifically, shows they understand its impact, and takes steps not to repeat it. The hurt partner can help by saying what they need to feel repaired, and noticing when those needs are met.", "tip": {"title": "A meaningful apology includes", "steps": ["Naming specifically what you did.", "Acknowledging how it affected your partner.", "Saying what you''ll do differently."]}}], "conclusion": "Forgiveness is a process, not a single moment. It grows when hurt is acknowledged and repair is consistent — and it frees both partners to focus on the relationship you''re building now."}'::jsonb, '["Forgiveness is letting go of resentment, not pretending hurt didn''t happen", "It doesn''t require forgetting or accepting ongoing harm", "Specific acknowledgment and changed behavior help forgiveness grow", "Forgiveness is gradual"]'::jsonb, '[{"title": "Clearing an old hurt", "description": "Gently address a small, lingering hurt.", "duration": "20 min", "instructions": ["Choose a small past hurt that still comes up (not the biggest one).", "The hurt partner shares its impact; the other listens and acknowledges it specifically.", "Together, name one thing that would help close it."]}]'::jsonb, '{"question": "Is there an old hurt that still affects how you see a situation today?", "followUp": "What would you need to begin letting it go?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Trust & Vulnerability (5 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('trust-vulnerability-series', 'Trust & Vulnerability', 'How safety grows through consistency, honesty, and paced openness.', 'Trust isn''t built in grand moments but in small, reliable ones. This series looks at how trust grows, how vulnerability deepens closeness, and how couples repair after trust has been hurt.', '🤝', 5, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('trust-vulnerability-series', 'how-trust-is-built', 'How Trust Is Built', 'Why trust grows in ordinary moments of choosing each other.', 'Why trust grows in ordinary moments of choosing each other.', '7 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "Trust can feel like a big, abstract thing, but it''s built in small, specific moments. Every time one partner needs something and the other shows up — or doesn''t — trust grows or wears down a little.", "sections": [{"title": "Sliding-door moments", "body": "Gottman calls these small choices \"sliding-door moments\": your partner seems upset, and you can ask what''s wrong or keep doing what you were doing. None of these moments is decisive alone. Together, they answer a quiet question each partner is always asking: \"Are you there for me?\"", "research": {"text": "Gottman''s work on trust describes how partners build it through repeated small moments of choosing to attune to each other rather than turning away.", "source": "Gottman, The Science of Trust", "year": 2011}}, {"title": "Trust is about more than fidelity", "body": "Trust covers many areas: Will you keep your word? Will you be kind when I''m vulnerable? Will you consider my needs when making decisions? Will you be honest with me? Each area can be strong or shaky, and it helps to talk about which areas feel solid and which need attention.", "tip": {"title": "Strengthening trust this week", "steps": ["Notice one moment when your partner seems to need you.", "Choose to turn toward them in that moment.", "Follow through on one small promise you''ve made."]}}], "conclusion": "Trust is built one ordinary moment at a time. Each time you show up for each other, you add to a foundation that can carry you through harder seasons."}'::jsonb, '["Trust is built in small, repeated moments", "Each moment answers \"Are you there for me?\"", "Trust spans many areas beyond fidelity", "Following through on small promises matters"]'::jsonb, '[{"title": "Trust inventory", "description": "Talk about which areas of trust feel strong.", "duration": "15 min", "instructions": ["Each rate how solid these feel (1–5): keeping promises, kindness when vulnerable, considering my needs, honesty.", "Share ratings and one example behind your highest one.", "Choose one area you''d both like to strengthen."]}]'::jsonb, '{"question": "In what area do you trust your partner most?", "followUp": "What is one small thing that would strengthen trust in another area?"}'::jsonb, 'draft'),
  ('trust-vulnerability-series', 'vulnerability', 'Vulnerability and Emotional Risk', 'Why letting your partner see your softer feelings deepens closeness.', 'Why letting your partner see your softer feelings deepens closeness.', '7 min', 2, ARRAY['Emotionally Focused Therapy']::text[], '{"introduction": "Many conflicts are fought with \"armor\" emotions like anger or irritation, while softer feelings — fear, hurt, loneliness, shame — stay hidden underneath. Sharing those softer feelings is risky, but it''s also what invites your partner closer.", "sections": [{"title": "Surface and underlying emotions", "body": "Anger is often a surface emotion protecting something more tender. \"You''re never home\" might really mean \"I''m scared I don''t matter to you.\" When partners only exchange surface emotions, both feel attacked. When one shares the underlying feeling, the other often softens.", "research": {"text": "Emotionally Focused Therapy is built on the idea that sharing underlying attachment emotions — like fear of rejection — helps partners respond to each other with care rather than defense.", "source": "Johnson, Hold Me Tight", "year": 2008}}, {"title": "Pacing vulnerability", "body": "Vulnerability grows best in steps. Start with something small and notice how your partner responds. When openness is met with care, it feels safer to share more. If it''s met with criticism or dismissal, it''s worth talking about gently, because that response makes future openness harder.", "tip": {"title": "Sharing a softer feeling", "steps": ["Notice the surface emotion first (irritation, anger).", "Ask yourself what feeling might be underneath.", "Try sharing it: \"Underneath my frustration, I think I''m feeling…\""]}}], "conclusion": "Vulnerability is how partners truly meet each other. Taking small risks — and meeting each other''s openness with care — makes the relationship a safe place to be known."}'::jsonb, '["Anger and irritation often protect softer feelings", "Sharing underlying feelings invites closeness", "Vulnerability grows in small, paced steps", "How openness is received shapes whether it continues"]'::jsonb, '[{"title": "Beneath the surface", "description": "Practice naming the feeling underneath a recent frustration.", "duration": "15 min", "instructions": ["Each think of a recent moment you felt irritated with your partner.", "Share the softer feeling that might have been underneath.", "The listener responds only with care and curiosity, not correction."]}]'::jsonb, '{"question": "Which softer feeling is hardest for you to show?", "followUp": "How could your partner make it easier to share?"}'::jsonb, 'draft'),
  ('trust-vulnerability-series', 'reliability', 'Reliability in Small Promises', 'How keeping everyday commitments quietly builds deep trust.', 'How keeping everyday commitments quietly builds deep trust.', '6 min', 3, ARRAY['Trust research']::text[], '{"introduction": "Big promises matter, but trust is usually built or eroded in smaller ones: calling when you said you would, doing the chore you agreed to, showing up on time. Each kept promise tells your partner that your word means something.", "sections": [{"title": "Predictability as a foundation", "body": "Research on trust describes it as developing in layers: first, partners learn that each other''s behavior is predictable; then, that they can be depended on; finally, a deeper faith that they''ll be there in the future. Everyday reliability is the first layer everything else builds on.", "research": {"text": "Early research on trust in close relationships described it as growing from predictability, to dependability, to faith in a partner''s ongoing care.", "source": "Rempel, Holmes & Zanna, Journal of Personality and Social Psychology", "year": 1985}}, {"title": "Promise less, keep more", "body": "A common trap is agreeing to more than you can do, then letting it slip. It builds more trust to say \"I can''t do that this week, but I can do this\" — and follow through — than to promise everything and deliver some of it. If you can''t keep a promise, telling your partner early matters.", "tip": {"title": "Building reliability", "steps": ["Only agree to what you can realistically do.", "If plans change, tell your partner as early as possible.", "Notice and thank your partner when they follow through."]}}], "conclusion": "Small, kept promises are the quiet backbone of trust. They tell your partner, again and again, that they can count on you."}'::jsonb, '["Trust grows from predictability to dependability to faith", "Small kept promises build the foundation", "Promising less and keeping more builds trust", "Telling your partner early when plans change protects trust"]'::jsonb, '[{"title": "Promise check", "description": "Look at the small commitments in your week.", "duration": "10 min", "instructions": ["Each list the small promises you''ve made to each other this week.", "Mark any that are at risk and decide how to handle them honestly.", "Each thank the other for one promise they kept recently."]}]'::jsonb, '{"question": "What small commitment from your partner means the most to you?", "followUp": "Which of your own commitments would you like to be more reliable about?"}'::jsonb, 'draft'),
  ('trust-vulnerability-series', 'rebuilding-trust', 'Rebuilding Trust After a Breach', 'How couples can begin to recover after a serious betrayal, including infidelity.', 'How couples can begin to recover after a serious betrayal, including infidelity.', '9 min', 4, ARRAY['Couple therapy research on affair recovery']::text[], '{"introduction": "When trust is seriously broken — through infidelity, a hidden debt, or a major lie — both partners often feel lost. The hurt partner may feel shock, grief, and anger; the partner who caused the hurt may feel shame and fear. Recovery is possible for many couples, but it takes time, honesty, and usually outside support.", "sections": [{"title": "Recovery happens in stages", "body": "Research on affair recovery describes a process: first, dealing with the immediate impact and emotional upheaval; then, understanding the context and factors that made the betrayal possible; and finally, moving forward — whether that means rebuilding the relationship or separating thoughtfully. Rushing to forgiveness usually backfires.", "research": {"text": "An integrative approach to affair recovery found that couples moving through stages — impact, understanding meaning, and moving on — showed improvement in individual and relationship well-being.", "source": "Gordon, Baucom & Snyder, Journal of Marital and Family Therapy", "year": 2004}}, {"title": "What helps early on", "body": "In the early stage, the hurt partner often needs honest answers to their questions, consistent transparency, and patience with intense emotions that come in waves. The partner who caused the breach helps most by taking full responsibility, not minimizing, and staying present with their partner''s pain. Working with a licensed couple therapist is strongly recommended for serious breaches.", "tip": {"title": "If you''re in this situation", "steps": ["Consider finding a licensed couple therapist experienced with betrayal.", "Avoid making permanent decisions in the first weeks of shock.", "Focus on honesty and consistency rather than rushing to move on."]}}], "conclusion": "A serious breach of trust is one of the hardest things a couple can face. With honesty, patience, and support, many couples find a path forward — sometimes to a relationship that''s more honest than before."}'::jsonb, '["Recovery from betrayal moves through stages", "Rushing to forgiveness usually backfires", "Full responsibility and transparency help the early stage", "Professional support is strongly recommended"]'::jsonb, '[{"title": "A gentle starting point", "description": "If you''re rebuilding trust, agree on how to talk about it safely.", "duration": "15 min", "instructions": ["Agree on a regular time to talk about the breach, rather than all the time.", "The hurt partner names what helps them feel safer right now.", "Discuss whether you''ll seek a couple therapist, and when."]}]'::jsonb, '{"question": "What does trust look like for you when it''s fully present?", "followUp": "What would be the first small sign that it''s beginning to rebuild?"}'::jsonb, 'draft'),
  ('trust-vulnerability-series', 'attachment-injuries', 'Attachment Injuries and Healing', 'When a moment of not being there becomes a lasting wound, and how couples heal it.', 'When a moment of not being there becomes a lasting wound, and how couples heal it.', '8 min', 5, ARRAY['Emotionally Focused Therapy', 'Attachment Theory']::text[], '{"introduction": "Sometimes a relationship is shaped by a single moment: a partner wasn''t there during a miscarriage, a hospital stay, or a family crisis. Even years later, the moment keeps coming up. These are called attachment injuries — moments when one partner felt abandoned at a time of deep need.", "sections": [{"title": "Why some moments don''t fade", "body": "Attachment injuries hurt so much because they strike at the core question of a relationship: \"Will you be there when I need you most?\" When the answer in a critical moment felt like \"no,\" the hurt partner may stay guarded, and the other partner may feel stuck being blamed for something they can''t undo.", "research": {"text": "Research on Emotionally Focused Therapy described attachment injuries as a specific kind of relational trauma and outlined steps couples take to resolve them.", "source": "Johnson, Makinen & Millikin, Journal of Marital and Family Therapy", "year": 2001}}, {"title": "How healing happens", "body": "Healing usually involves the hurt partner describing the moment and its impact, and the other partner staying present — not defending, but acknowledging the pain and expressing genuine regret. When the hurt partner then risks sharing their need for comfort, and the other responds with care, the injury can begin to close.", "tip": {"title": "If a past moment keeps coming up", "steps": ["Name it as something that still hurts, not an accusation.", "The other partner listens for the pain, not the charge.", "Consider a therapist trained in Emotionally Focused Therapy."]}}], "conclusion": "Attachment injuries can shape a relationship for years, but they can heal. When pain is heard and met with genuine care, old wounds can become moments of renewed trust."}'::jsonb, '["Attachment injuries are moments of feeling abandoned in deep need", "They keep resurfacing because they touch the core question of the relationship", "Healing requires acknowledgment, not defense", "Emotionally Focused Therapy offers a clear path for this work"]'::jsonb, '[{"title": "Naming an old wound", "description": "Gently explore whether a past moment still affects you.", "duration": "20 min", "instructions": ["Each consider whether there''s a moment when you felt alone when you needed your partner.", "If you''re ready, share it using \"I felt…\" language.", "The listener reflects the pain they hear before saying anything else."]}]'::jsonb, '{"question": "Is there a moment in your relationship that still feels unresolved?", "followUp": "What would your partner need to understand about it?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Intimacy (5 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('intimacy-series', 'Intimacy', 'How emotional, physical, intellectual, and shared-time closeness all matter.', 'Intimacy is more than sex, and sex is more than technique. This series looks at the different kinds of closeness, how to talk about physical intimacy, differences in desire, body image, and keeping intimacy alive over the long term.', '💞', 6, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('intimacy-series', 'kinds-of-closeness', 'Four Kinds of Closeness', 'Emotional, physical, intellectual, and shared-experience intimacy — and which ones each of you needs most.', 'Emotional, physical, intellectual, and shared-experience intimacy — and which ones each of you needs most.', '6 min', 1, ARRAY['Intimacy process research']::text[], '{"introduction": "When couples say they want more intimacy, they don''t always mean the same thing. One partner may be longing for deeper conversation; the other, more physical affection. Naming the different kinds of closeness helps couples understand what each person is actually missing.", "sections": [{"title": "The four kinds", "body": "• Emotional: sharing feelings and feeling understood.\n• Physical: touch, affection, and sexual connection.\n• Intellectual: sharing ideas, opinions, and curiosity.\n• Shared experience: doing things together and building memories.\n\nMost people value all four, but in different proportions — and those proportions can shift over time.", "research": {"text": "Research describes intimacy as a process: one partner''s disclosure, met with a responsive reply, creates a feeling of being understood, valued, and cared for.", "source": "Laurenceau, Barrett & Pietromonaco, Journal of Personality and Social Psychology", "year": 1998}}, {"title": "Responsiveness is the common thread", "body": "Whatever kind of closeness you''re building, the key ingredient is responsiveness: your partner shares something, and you respond in a way that shows you understand and care. That''s what makes a conversation, a touch, or a shared evening feel intimate rather than just routine.", "tip": {"title": "Mapping your closeness needs", "steps": ["Each rank the four kinds by how important they feel right now.", "Compare rankings without trying to change each other''s.", "Plan one small moment this week for each partner''s top kind."]}}], "conclusion": "Understanding the kinds of closeness each of you needs turns vague longing into something specific you can offer each other."}'::jsonb, '["Intimacy comes in emotional, physical, intellectual, and shared-experience forms", "Partners often value them in different proportions", "Responsiveness makes any kind of closeness feel intimate", "Naming what''s missing makes it easier to offer"]'::jsonb, '[{"title": "Closeness ranking", "description": "Compare which kinds of closeness matter most to each of you right now.", "duration": "15 min", "instructions": ["Each privately rank the four kinds of intimacy.", "Share your rankings and one example of when you felt each kind.", "Choose one moment to create this week for each partner''s top kind."]}]'::jsonb, '{"question": "Which kind of closeness do you feel is most missing right now?", "followUp": "What would a small moment of it look like?"}'::jsonb, 'draft'),
  ('intimacy-series', 'talking-about-sex', 'Talking About Sex', 'Why couples who can talk openly about sex tend to feel more satisfied — and how to start.', 'Why couples who can talk openly about sex tend to feel more satisfied — and how to start.', '7 min', 2, ARRAY['Sexual communication research']::text[], '{"introduction": "Many couples find it easier to have sex than to talk about it. Yet conversations about likes, dislikes, and desires are one of the most reliable paths to a more satisfying sexual relationship. These conversations can feel awkward at first, and that''s normal.", "sections": [{"title": "Why talking helps", "body": "Partners can''t read each other''s minds. Sharing what you enjoy and what you''d like more of helps each person understand the other better, and makes it easier to adjust over time as preferences change.", "research": {"text": "Research with long-term couples found that sharing sexual likes and dislikes was associated with greater sexual satisfaction, partly because it helped partners understand each other''s preferences.", "source": "MacNeil & Byers, Journal of Sex Research", "year": 2009}}, {"title": "Making the conversation easier", "body": "Choose a relaxed moment outside the bedroom. Start with appreciation (\"I love it when…\") before requests. Use curiosity rather than critique, and remember that preferences aren''t performance reviews. It''s okay to go slowly and come back to the topic over time.", "tip": {"title": "Conversation starters", "steps": ["\"What''s something that makes you feel especially close to me physically?\"", "\"Is there anything you''ve been curious about but haven''t mentioned?\"", "\"What helps you feel relaxed and in the mood?\""]}}], "conclusion": "Talking about sex doesn''t have to be a big, dramatic conversation. Small, curious, appreciative conversations over time build a sexual relationship that fits both of you."}'::jsonb, '["Open sexual communication is linked to greater satisfaction", "Partners can''t read each other''s minds", "Starting with appreciation makes requests easier to hear", "These conversations can happen gradually"]'::jsonb, '[{"title": "An appreciative start", "description": "Begin a low-pressure conversation about physical intimacy.", "duration": "15 min", "instructions": ["Choose a relaxed time outside the bedroom.", "Each share one thing you appreciate about your physical relationship.", "If it feels okay, each share one thing you''d like more of."]}]'::jsonb, '{"question": "What makes it hard for you to talk about sex with your partner?", "followUp": "What would help it feel more comfortable?"}'::jsonb, 'draft'),
  ('intimacy-series', 'desire-differences', 'Desire Differences', 'Why partners often want sex at different times or frequencies, and how to handle it kindly.', 'Why partners often want sex at different times or frequencies, and how to handle it kindly.', '8 min', 3, ARRAY['Sexual response research']::text[], '{"introduction": "Differences in sexual desire are among the most common challenges couples face. They often lead to a painful cycle: one partner feels rejected, the other feels pressured, and both start avoiding the topic. Understanding how desire works can take a lot of the blame out of it.", "sections": [{"title": "Spontaneous and responsive desire", "body": "Some people experience desire that seems to appear out of nowhere — spontaneous desire. Others more often feel desire after physical closeness has already begun — responsive desire. Both are normal. A partner with more responsive desire isn''t uninterested; they may simply need connection, relaxation, or touch first.", "research": {"text": "An influential model of sexual response described how desire can be responsive — arising after intimacy begins, often motivated by wanting closeness — rather than always coming first.", "source": "Basson, Journal of Sex & Marital Therapy", "year": 2000}}, {"title": "Stepping out of the pressure cycle", "body": "It often helps to separate affection from expectation: physical touch that doesn''t have to lead anywhere can make closeness feel safe again. Talking about what helps each of you feel relaxed and open — and what gets in the way, like stress or fatigue — makes the difference feel like a shared puzzle rather than a personal rejection.\n\nIf desire differences cause ongoing distress, a certified sex therapist can help.", "tip": {"title": "Reducing the pressure", "steps": ["Agree on some affection that doesn''t need to lead to sex.", "Each share what helps you feel open to intimacy.", "Each share what tends to get in the way (stress, tiredness, timing)."]}}], "conclusion": "Desire differences are normal and workable. Understanding how each of you experiences desire replaces rejection and pressure with curiosity and care."}'::jsonb, '["Desire differences are very common", "Desire can be spontaneous or responsive — both are normal", "Affection without expectation can reduce pressure", "A certified sex therapist can help with ongoing distress"]'::jsonb, '[{"title": "What helps and what hinders", "description": "Understand the conditions that help each of you feel open to intimacy.", "duration": "15 min", "instructions": ["Each list three things that help you feel relaxed and open.", "Each list three things that make intimacy feel harder.", "Choose one helper you can offer each other this week."]}]'::jsonb, '{"question": "What helps you feel most relaxed and open with your partner?", "followUp": "How could the two of you protect those conditions more often?"}'::jsonb, 'draft'),
  ('intimacy-series', 'body-image', 'Body Image and Feeling Wanted', 'How self-consciousness affects closeness, and how partners can support each other.', 'How self-consciousness affects closeness, and how partners can support each other.', '6 min', 4, ARRAY['Couple and body-image practice']::text[], '{"introduction": "How people feel about their own bodies can deeply affect intimacy. Self-consciousness after weight changes, pregnancy, aging, illness, or long-held insecurities can make it hard to relax and feel wanted — even with a loving partner.", "sections": [{"title": "Self-consciousness gets in the way", "body": "When someone is worried about how they look, part of their attention stays on themselves instead of on the connection. They may avoid certain positions, keep the lights off, or avoid intimacy altogether. The partner may misread this as a lack of interest in them."}, {"title": "Supporting each other", "body": "Reassurance helps most when it''s specific and genuine, and when it focuses on how your partner makes you feel rather than evaluating their body. Just as important is listening when your partner shares insecurity, rather than rushing to dismiss it (\"don''t be silly\"). Being heard often helps more than being contradicted.", "tip": {"title": "Kind ways to respond", "steps": ["Listen before reassuring.", "Share what you find attractive or loving about being with them, specifically.", "Ask what would help them feel more comfortable."]}}], "conclusion": "Feeling wanted is a big part of feeling close. Gentle curiosity and genuine appreciation help partners feel safe to show up as they are."}'::jsonb, '["Self-consciousness can pull attention away from connection", "Avoidance can be misread as lack of interest", "Listening matters as much as reassuring", "Specific, genuine appreciation helps partners feel wanted"]'::jsonb, '[{"title": "Feeling wanted", "description": "Share what helps each of you feel desired and at ease.", "duration": "10 min", "instructions": ["Each share one moment when you felt especially wanted by your partner.", "Each share one thing that makes you feel self-conscious, if you''re comfortable.", "The listener responds with curiosity and care, not correction."]}]'::jsonb, '{"question": "When do you feel most at ease in your own body with your partner?", "followUp": "What helps create that feeling?"}'::jsonb, 'draft'),
  ('intimacy-series', 'keeping-intimacy-alive', 'Keeping Intimacy Alive', 'Protecting closeness and physical connection through busy, long-term seasons.', 'Protecting closeness and physical connection through busy, long-term seasons.', '7 min', 5, ARRAY['Sexual well-being research']::text[], '{"introduction": "In long relationships, intimacy often drifts to the bottom of the to-do list. Work, children, and fatigue take priority, and closeness happens only when there''s leftover energy — which is rarely. Keeping intimacy alive usually means treating it as something worth protecting.", "sections": [{"title": "Quality over quantity", "body": "There isn''t a \"right\" amount of sex for couples. What seems to matter more is that both partners feel connected and that intimacy is part of their relationship in a way that works for them.", "research": {"text": "A large study found that sexual frequency was linked with well-being up to about once a week, with no further benefit beyond that — suggesting that connection matters more than hitting a number.", "source": "Muise, Schimmack & Impett, Social Psychological and Personality Science", "year": 2016}}, {"title": "Making room for closeness", "body": "Planning intimacy can feel unromantic, but for many busy couples it''s what makes it happen at all. Scheduled time together, rituals of affection (a real kiss goodbye, cuddling before sleep), and small signals of desire through the day help keep physical closeness part of everyday life.", "tip": {"title": "Small habits that help", "steps": ["A lingering kiss when you reunite each day.", "A regular evening with no screens and no chores.", "Sending a small, affectionate message during the day."]}}], "conclusion": "Intimacy thrives when it''s protected, not when it''s left to chance. Small, deliberate moments of closeness keep it alive through every season."}'::jsonb, '["Intimacy often drifts in busy seasons", "Connection matters more than frequency", "Planning can make closeness possible, not less romantic", "Small daily rituals keep physical connection alive"]'::jsonb, '[{"title": "Protect your closeness", "description": "Choose small habits to protect intimacy.", "duration": "15 min", "instructions": ["Each name what most often crowds out time for intimacy.", "Pick two small habits from the list above (or your own).", "Decide on one protected evening in the next two weeks."]}]'::jsonb, '{"question": "What helps you feel most connected physically to your partner?", "followUp": "What''s one thing you could protect time for?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Life & Growth (7 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('life-growth-series', 'Life & Growth', 'How everyday systems like roles, family, parenting, technology, and distance shape the relationship.', 'Relationships don''t happen in a vacuum. This series covers the practical life areas that shape how couples feel together: expectations and roles, extended family, becoming parents, traditions, technology, distance, and growing as individuals.', '🌱', 7, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('life-growth-series', 'expectations-roles', 'Expectations and Roles', 'Making unspoken expectations about household roles and responsibilities visible.', 'Making unspoken expectations about household roles and responsibilities visible.', '7 min', 1, ARRAY['Family and household-labor research']::text[], '{"introduction": "Many couples fight about chores, but the real issue is usually unspoken expectations: who notices what needs doing, who plans, who remembers. When these expectations stay hidden, one partner often feels overwhelmed and the other feels criticized.", "sections": [{"title": "The invisible work", "body": "Household work includes not just doing tasks but thinking about them: remembering appointments, noticing the fridge is empty, planning birthdays. This \"mental load\" is often invisible to the partner who isn''t carrying it, which can leave the other feeling alone even when tasks are shared.", "research": {"text": "Research on dual-earner couples described how household and care work often remains unevenly shared, creating a \"second shift\" that strains relationships.", "source": "Hochschild, The Second Shift", "year": 1989}}, {"title": "Making it visible", "body": "A helpful step is listing everything it takes to run your shared life — including planning and remembering — and discussing who owns each area fully, from noticing to finishing. Ownership reduces reminding and resentment.", "tip": {"title": "Dividing ownership", "steps": ["List household areas, including planning and remembering tasks.", "Assign each area to one owner who handles it from start to finish.", "Revisit the split in a month and adjust."]}}], "conclusion": "Most role conflicts are really about unspoken expectations. Making the invisible work visible lets you share the load in a way that feels fair to both of you."}'::jsonb, '["Many chore conflicts are really about unspoken expectations", "The mental load of noticing and planning is often invisible", "Full ownership of areas reduces reminding and resentment", "Divisions of labor should be revisited over time"]'::jsonb, '[{"title": "Map the load", "description": "Make your household work visible and share it deliberately.", "duration": "25 min", "instructions": ["Together, list every area of running your shared life.", "Mark who currently notices, plans, and does each one.", "Choose one area to hand over fully, with a check-in in a month."]}]'::jsonb, '{"question": "What task do you carry that you think your partner may not notice?", "followUp": "How would you like to share it?"}'::jsonb, 'draft'),
  ('life-growth-series', 'in-laws', 'In-Laws and Family Boundaries', 'Protecting your relationship while staying connected to both families.', 'Protecting your relationship while staying connected to both families.', '7 min', 2, ARRAY['Family systems practice']::text[], '{"introduction": "When two people build a life together, they also join two families with their own traditions, expectations, and ways of doing things. Tension with in-laws is common — and how a couple handles it together matters more than the tension itself.", "sections": [{"title": "Your relationship comes first", "body": "Couples tend to do best when they present a united front: decisions about holidays, visits, and parenting are made together, and each partner handles communication with their own family. When one partner feels their spouse sides with their family over them, it can deeply hurt trust."}, {"title": "Setting boundaries with warmth", "body": "Boundaries don''t have to be cold. They can be kind and clear: \"We love having you visit. This year, we''re spending the holiday at home, and we''d love to see you the weekend after.\" Agreeing on boundaries privately first, then sharing them together, helps both partners feel supported.", "tip": {"title": "Handling a family tension", "steps": ["Talk it through privately first and agree on a shared position.", "Each partner handles conversations with their own family.", "Keep boundaries clear and warm."]}}], "conclusion": "Families can be a great source of support and a real source of strain. Facing family questions as a team protects your relationship and your connection to the people you love."}'::jsonb, '["How a couple handles family tension matters more than the tension", "Decisions about families work best when made together", "Each partner usually handles their own family", "Boundaries can be both warm and clear"]'::jsonb, '[{"title": "Family game plan", "description": "Talk through an upcoming family situation.", "duration": "15 min", "instructions": ["Pick an upcoming holiday, visit, or family decision.", "Each share your hopes and worries about it.", "Agree on a shared plan and who will communicate it."]}]'::jsonb, '{"question": "When do you feel most supported by your partner around your family?", "followUp": "What''s one family situation where you''d like more teamwork?"}'::jsonb, 'draft'),
  ('life-growth-series', 'becoming-parents', 'Becoming Parents Together', 'Protecting your relationship through the big transition to parenthood.', 'Protecting your relationship through the big transition to parenthood.', '8 min', 3, ARRAY['Gottman Method (Bringing Baby Home research)']::text[], '{"introduction": "Having a baby is one of the most joyful — and most stressful — transitions a couple can go through. Sleep deprivation, new roles, and less time together put real pressure on the relationship. Many couples notice more conflict and less closeness in the first years, and it helps to know that''s common.", "sections": [{"title": "What protects couples through the transition", "body": "Couples who stay closer through the transition tend to keep up fondness for each other, stay aware of each other''s lives, and approach problems as a team. Small daily moments of connection matter even more when time is scarce.", "research": {"text": "A study following couples through the transition to parenthood found that fondness, affection, and awareness of each other''s lives protected against declines in relationship satisfaction after a baby arrived.", "source": "Shapiro, Gottman & Carrère, Journal of Family Psychology", "year": 2000}}, {"title": "Practical ways to stay a team", "body": "Discuss expectations about sleep, feeding, and household tasks before you''re exhausted. Protect even ten minutes a day to talk about something other than logistics. Notice and thank each other for the invisible work. And remember that both partners are learning — criticism lands especially hard when everyone is tired.", "tip": {"title": "Small protections", "steps": ["A daily ten-minute check-in that isn''t about logistics.", "Taking turns protecting each other''s sleep.", "Saying thank you for specific things, every day."]}}], "conclusion": "Becoming parents changes a relationship, but it doesn''t have to weaken it. Small, deliberate acts of fondness and teamwork carry couples through the most demanding early years."}'::jsonb, '["More stress and conflict after a baby is common", "Fondness and awareness of each other protect the relationship", "Discussing expectations early prevents resentment", "Small daily connection matters even more when time is scarce"]'::jsonb, '[{"title": "Parenting team plan", "description": "Talk through expectations before or during the transition.", "duration": "20 min", "instructions": ["Each share your expectations about nights, feeding, and household tasks.", "Notice where your expectations differ.", "Agree on one daily ritual that keeps you connected as a couple."]}]'::jsonb, '{"question": "What do you most want to protect in your relationship as parents?", "followUp": "What''s one way your partner could support you right now?"}'::jsonb, 'draft'),
  ('life-growth-series', 'family-culture', 'Family Culture and Traditions', 'Blending two family backgrounds into traditions that feel like yours.', 'Blending two family backgrounds into traditions that feel like yours.', '6 min', 4, ARRAY['Family systems practice']::text[], '{"introduction": "Each partner brings a lifetime of habits and traditions from their family: how holidays are celebrated, how birthdays are marked, how conflict is handled, how money is talked about. Building a shared life means deciding which traditions to keep, blend, or create new.", "sections": [{"title": "Your family of origin shows up", "body": "Many small conflicts (\"That''s not how you do Christmas!\") are really about family culture. What feels normal to one partner may feel strange to the other. Neither is right; they''re just different starting points."}, {"title": "Creating your own culture", "body": "Couples can intentionally build their own traditions: keeping cherished rituals from each family, dropping ones that don''t fit, and creating new ones that reflect who they are together. This gives the relationship its own identity.", "tip": {"title": "Blending traditions", "steps": ["Each share one tradition from your family you''d love to keep.", "Each share one you''d prefer to leave behind.", "Create one brand-new tradition that''s just yours."]}}], "conclusion": "Your relationship gets to have its own culture. Blending the best of where you each came from — and adding something new — is part of building a shared life."}'::jsonb, '["Each partner brings family habits and traditions", "Many small conflicts come from different family cultures", "Couples can choose which traditions to keep, blend, or create", "Shared traditions give a relationship its own identity"]'::jsonb, '[{"title": "Traditions conversation", "description": "Choose traditions to keep and create.", "duration": "15 min", "instructions": ["Each share a favorite childhood tradition and what it meant.", "Identify one tradition to keep and one to adapt.", "Brainstorm one new tradition to start this year."]}]'::jsonb, '{"question": "What tradition from your family do you most want to carry forward?", "followUp": "What new tradition would feel meaningful to create together?"}'::jsonb, 'draft'),
  ('life-growth-series', 'technology', 'Technology and Attention', 'How phones and screens can crowd out connection — and simple ways to protect time together.', 'How phones and screens can crowd out connection — and simple ways to protect time together.', '6 min', 5, ARRAY['Technoference research']::text[], '{"introduction": "Phones make it easy to be physically together but mentally elsewhere. Checking a notification during a conversation or scrolling in bed can feel minor, but over time, repeated interruptions can leave partners feeling less important than a screen.", "sections": [{"title": "\"Technoference\" adds up", "body": "Everyday interruptions by technology — sometimes called technoference — can create small moments of disconnection. Individually they''re tiny; together they can make a partner feel less noticed.", "research": {"text": "Research found that more frequent technology interruptions in couple interactions were associated with more conflict over technology and lower relationship satisfaction.", "source": "McDaniel & Coyne, Psychology of Popular Media Culture", "year": 2016}}, {"title": "Setting gentle limits together", "body": "The goal isn''t to ban screens but to agree on protected moments: meals, the first ten minutes after coming home, the last half hour before sleep. Agreements work better than policing, and they work best when both partners follow them.", "tip": {"title": "Phone-free moments to try", "steps": ["Meals without phones at the table.", "The first ten minutes after reuniting.", "Phones out of the bedroom, or away 30 minutes before sleep."]}}], "conclusion": "Technology isn''t the enemy of connection, but it can quietly crowd it out. A few protected, screen-free moments can make a big difference."}'::jsonb, '["Small technology interruptions can add up", "Frequent interruptions are linked to lower satisfaction", "Shared agreements work better than policing", "Protected screen-free moments help connection"]'::jsonb, '[{"title": "Screen agreement", "description": "Agree on protected, phone-free moments.", "duration": "10 min", "instructions": ["Each name the moment when screens bother you most.", "Choose one or two phone-free times to try.", "Check in after a week on how it''s going."]}]'::jsonb, '{"question": "When do you most wish your partner''s full attention was with you?", "followUp": "What screen habit of your own would you like to change?"}'::jsonb, 'draft'),
  ('life-growth-series', 'long-distance', 'Long-Distance Seasons', 'Staying close when work, study, or life keeps you physically apart.', 'Staying close when work, study, or life keeps you physically apart.', '6 min', 6, ARRAY['Long-distance relationship research']::text[], '{"introduction": "Distance — whether from deployment, work travel, study, or immigration processes — is hard. But long-distance relationships aren''t doomed. Many couples find ways to stay deeply connected, and some even report feeling closer because they communicate more intentionally.", "sections": [{"title": "What helps distance couples", "body": "Long-distance couples often share more openly and idealize each other somewhat, which can actually help intimacy. The challenges tend to come from missing everyday moments and from reunions and goodbyes that are emotionally intense.", "research": {"text": "A study comparing couples found that long-distance partners often shared more about themselves and felt as much or more intimacy than geographically close couples.", "source": "Jiang & Hancock, Journal of Communication", "year": 2013}}, {"title": "Staying part of each other''s day", "body": "Sharing small, everyday details — photos of lunch, a voice note on the way to work, watching a show at the same time — helps partners stay present in each other''s ordinary lives, not just the big conversations. Having a plan for the next visit also gives both people something to look forward to.", "tip": {"title": "Distance habits", "steps": ["Share one small everyday moment each day.", "Have a regular call time that both protect.", "Always know when you''ll see each other next."]}}], "conclusion": "Distance changes how couples connect, but it doesn''t have to weaken the connection. Intentional, everyday sharing keeps partners part of each other''s lives."}'::jsonb, '["Long-distance couples can feel as close as nearby couples", "Missing everyday moments is a key challenge", "Sharing small daily details keeps partners present", "Knowing when you''ll next see each other helps"]'::jsonb, '[{"title": "Distance plan", "description": "Create habits for staying connected across distance.", "duration": "15 min", "instructions": ["Each name what you miss most about being together day to day.", "Choose two small daily sharing habits.", "Agree on a regular call time and plan your next visit."]}]'::jsonb, '{"question": "What makes you feel closest to your partner when you''re apart?", "followUp": "What''s one new way you could share everyday moments?"}'::jsonb, 'draft'),
  ('life-growth-series', 'growing-together', 'Growing Individually, Together', 'Why supporting each other''s growth strengthens the relationship.', 'Why supporting each other''s growth strengthens the relationship.', '6 min', 7, ARRAY['Self-expansion research']::text[], '{"introduction": "Strong relationships aren''t just about the two of you merging into one. Each partner also keeps growing — new skills, interests, friendships, and goals. Supporting each other''s individual growth tends to make the relationship richer, not weaker.", "sections": [{"title": "Relationships as a source of growth", "body": "People are drawn to relationships partly because they expand who we are: new perspectives, new experiences, new parts of ourselves. When partners keep supporting each other''s growth, the relationship remains a source of that expansion.", "research": {"text": "Self-expansion theory proposes that people are motivated to grow, and that relationships which help each partner expand their sense of self tend to be more satisfying.", "source": "Aron & Aron, Love and the Expansion of Self", "year": 1986}}, {"title": "Supporting each other''s goals", "body": "Supporting growth can mean making room for a partner''s class, cheering on a career change, or respecting time for friendships and hobbies. It also means sharing your own goals so your partner can support you.", "tip": {"title": "Supporting growth", "steps": ["Ask your partner about a goal they''re working toward.", "Ask what support would actually help.", "Celebrate progress, not just finish lines."]}}], "conclusion": "Growing as individuals doesn''t pull a couple apart when both partners support each other''s journeys. It keeps the relationship full of new things to share."}'::jsonb, '["Each partner keeps growing throughout a relationship", "Relationships that support growth tend to be more satisfying", "Support includes making room for goals, friendships, and interests", "Sharing your goals lets your partner support you"]'::jsonb, '[{"title": "Growth goals", "description": "Share personal goals and how to support each other.", "duration": "15 min", "instructions": ["Each share one personal goal for the next six months.", "Each ask: \"What would support look like for this?\"", "Agree on one concrete way to support each goal."]}]'::jsonb, '{"question": "What''s a part of yourself you''d like to grow in the coming year?", "followUp": "How could your partner support you in it?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Health & Wellness (7 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('health-wellness-series', 'Health & Wellness', 'How stress, mental health, illness, transitions, and money shape a relationship — and how couples cope together.', 'Life brings stress from outside the relationship: work pressure, anxiety, low mood, illness, big transitions, and money worries. This series looks at how couples can face these challenges as a team, and when outside support can help.', '🌿', 8, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('health-wellness-series', 'dyadic-coping', 'Coping With Stress Together', 'How stress from outside the relationship spills in, and how couples can cope as a team.', 'How stress from outside the relationship spills in, and how couples can cope as a team.', '7 min', 1, ARRAY['Dyadic coping research']::text[], '{"introduction": "Stress from work, family, or health rarely stays outside the front door. When one partner is stressed, they may be more irritable, more withdrawn, or less patient — and the relationship feels the strain. How a couple handles stress together can matter as much as the stress itself.", "sections": [{"title": "Stress spillover", "body": "When people are under outside pressure, they have less energy for patience and kindness at home. Small annoyances feel bigger, and partners can end up arguing about the dishes when the real issue is a hard week at work. Recognizing spillover helps couples respond to the stress rather than to each other.", "research": {"text": "A review of research found that stress from outside the relationship is linked to lower relationship satisfaction, partly because it leaves partners with less time and energy for each other.", "source": "Randall & Bodenmann, Clinical Psychology Review", "year": 2009}}, {"title": "Coping as a \"we\"", "body": "Couples cope best when stress is treated as a shared challenge: one partner shares what''s weighing on them, and the other responds with understanding, practical help, or both. This is sometimes called dyadic coping. It works best when the stressed partner says what kind of support they want.", "research": {"text": "Research on dyadic coping found that couples who support each other through stress, and face shared stressors together, tend to report higher relationship quality.", "source": "Bodenmann, in Couples Coping with Stress (APA)", "year": 2005}, "tip": {"title": "Asking for the support you need", "steps": ["Name the stress: \"Work has been really heavy this week.\"", "Say what would help: listening, practical help, or space.", "Thank your partner when they offer it."]}}], "conclusion": "Stress will always find its way into a relationship. Couples who notice it and face it together turn a source of strain into a source of closeness."}'::jsonb, '["Outside stress often spills into the relationship", "Arguments can be about stress rather than each other", "Facing stress as a team strengthens relationships", "Saying what kind of support you need helps it land"]'::jsonb, '[{"title": "Stress check-in", "description": "Share current stresses and the support that would help.", "duration": "15 min", "instructions": ["Each name the biggest stress outside the relationship right now.", "Each say whether you''d like listening, practical help, or space.", "Agree on one way to support each other this week."]}]'::jsonb, '{"question": "How does stress tend to show up in how you treat your partner?", "followUp": "What kind of support helps you most when you''re stressed?"}'::jsonb, 'draft'),
  ('health-wellness-series', 'anxiety', 'When Anxiety Is Part of the Relationship', 'Supporting a partner with anxiety without taking it on yourself.', 'Supporting a partner with anxiety without taking it on yourself.', '7 min', 2, ARRAY['Cognitive-behavioral couple practice']::text[], '{"introduction": "Anxiety is common, and when one or both partners live with it, it can shape the relationship: frequent reassurance-seeking, avoidance of certain situations, or worry that spills into everyday plans. Partners often want to help but aren''t sure how.", "sections": [{"title": "Support without accommodation", "body": "A natural way to help an anxious partner is to accommodate: answering the same reassurance question many times, avoiding places that cause worry, or taking over tasks. In the short term this brings relief, but over time it can keep anxiety going. Supportive responses acknowledge the worry while gently encouraging your partner''s own coping.", "example": {"scenario": "One partner asks for the third time whether the other is upset with them.", "dialogue": "\"I can hear you''re really worried. I''m not upset with you. What do you think might help the worry settle a bit?\"", "analysis": "This response acknowledges the feeling and reassures once, then invites the partner''s own coping rather than repeating reassurance."}}, {"title": "Looking after yourselves", "body": "Supporting an anxious partner is easier when both of you understand the anxiety and agree on how to handle it. The partner without anxiety needs care too; it''s okay to have limits. When anxiety significantly affects daily life, a licensed therapist can help — and couple-based approaches can include both partners.", "tip": {"title": "A shared plan", "steps": ["Talk about how anxiety shows up for the anxious partner.", "Agree on what''s helpful support and what tends to feed the worry.", "Consider professional help if anxiety is affecting daily life."]}}], "conclusion": "Anxiety doesn''t have to come between partners. Understanding it together and agreeing on how to respond can make it something you manage as a team."}'::jsonb, '["Anxiety is common and can shape relationship patterns", "Too much accommodation can keep anxiety going", "Supportive responses acknowledge worry and encourage coping", "Both partners'' needs matter; professional help is valuable"]'::jsonb, '[{"title": "Anxiety plan", "description": "Agree on how to respond when anxiety shows up.", "duration": "20 min", "instructions": ["The partner who experiences anxiety describes how it shows up.", "Together, list responses that help and ones that seem to feed the worry.", "Agree on one phrase you''ll use when anxiety rises."]}]'::jsonb, '{"question": "How does worry or anxiety show up in your relationship?", "followUp": "What response from your partner helps you feel steadier?"}'::jsonb, 'draft'),
  ('health-wellness-series', 'low-mood', 'Depression and Low Mood', 'How low mood affects a relationship, and how partners can care for each other.', 'How low mood affects a relationship, and how partners can care for each other.', '8 min', 3, ARRAY['Couple and depression research']::text[], '{"introduction": "When one partner is going through depression or a long stretch of low mood, both people feel it. The partner who is struggling may withdraw, feel numb, or have little energy; the other may feel lonely, helpless, or frustrated. Neither person is to blame.\n\nIf either of you is thinking about self-harm or suicide, reach out right away: contact local emergency services, or in the US call or text 988 (Suicide & Crisis Lifeline).", "sections": [{"title": "Depression and relationships influence each other", "body": "Depression can make it harder to connect, and relationship stress can make low mood worse. That can create a painful cycle — but it also means that a supportive relationship can be part of recovery.", "research": {"text": "A meta-analysis found a consistent link between relationship distress and depressive symptoms, for both men and women.", "source": "Whisman, in Marital and Family Processes in Depression (APA)", "year": 2001}}, {"title": "Caring without fixing", "body": "Depression isn''t something a partner can fix, and trying to cheer someone up can leave them feeling misunderstood. What tends to help more: staying present, keeping gentle routines of connection, encouraging professional support, and not taking withdrawal personally. The supporting partner also needs their own support — from friends, activities, and sometimes a therapist.", "tip": {"title": "Gentle ways to help", "steps": ["Offer company without pressure: \"Want me to sit with you?\"", "Keep small rituals going, like a short walk or a shared meal.", "Encourage — and help arrange — support from a doctor or therapist."]}}], "conclusion": "Low mood can make a relationship feel distant, but it doesn''t define it. Patience, presence, and professional support help couples get through it together."}'::jsonb, '["Depression affects both partners, and neither is to blame", "Low mood and relationship stress can feed each other", "Presence helps more than trying to fix", "Professional support and self-care for both partners matter"]'::jsonb, '[{"title": "Support conversation", "description": "Talk about what helps during low times.", "duration": "15 min", "instructions": ["Choose a calmer moment to talk.", "The partner who experiences low mood shares what helps and what doesn''t.", "The supporting partner shares what they need to stay well too."]}]'::jsonb, '{"question": "What do you need from your partner when you''re feeling low?", "followUp": "What helps you look after yourself while supporting them?"}'::jsonb, 'draft'),
  ('health-wellness-series', 'illness-caregiving', 'Illness and Caregiving', 'Staying partners, not just patient and caregiver, through health challenges.', 'Staying partners, not just patient and caregiver, through health challenges.', '8 min', 4, ARRAY['Dyadic coping with chronic illness']::text[], '{"introduction": "A serious or chronic illness changes a relationship. Roles shift, plans change, and one partner may take on caregiving tasks. Couples often find that illness brings both closeness and strain — and that it helps to talk openly about both.", "sections": [{"title": "Illness as a shared challenge", "body": "Couples tend to cope better when they see illness as \"our\" challenge rather than one person''s problem, while still respecting that the ill partner has their own experience. Talking together about treatment decisions, fears, and practical needs helps both partners feel less alone.", "research": {"text": "A review of couples coping with chronic illness found that facing illness as a shared stressor, and collaborating on coping, was linked to better adjustment for both partners.", "source": "Berg & Upchurch, Psychological Bulletin", "year": 2007}}, {"title": "Protecting the partnership", "body": "When caregiving takes over, couples can lose the parts of their relationship that aren''t about illness. Protecting time for ordinary connection — a favorite show, a joke, a conversation about something else — helps keep you partners, not just patient and caregiver. Caregivers need rest and support too.", "tip": {"title": "Keeping the partnership alive", "steps": ["Set aside time where illness isn''t the topic.", "Let the ill partner contribute where they can.", "Make sure the caregiver has regular breaks and support."]}}], "conclusion": "Illness can reshape a relationship, but it doesn''t have to replace it. Facing it together while protecting everyday connection helps couples stay close."}'::jsonb, '["Illness shifts roles and plans for both partners", "Seeing illness as a shared challenge helps adjustment", "Protect time for connection that isn''t about illness", "Caregivers need rest and support too"]'::jsonb, '[{"title": "Beyond the illness", "description": "Plan ways to stay connected beyond illness and caregiving.", "duration": "15 min", "instructions": ["Each share one thing you miss about your relationship before the illness.", "Choose one small activity that isn''t about health.", "Talk about what support the caregiving partner needs."]}]'::jsonb, '{"question": "What helps you feel like partners, not just patient and caregiver?", "followUp": "What is one thing you''d like more of together?"}'::jsonb, 'draft'),
  ('health-wellness-series', 'transitions', 'Navigating Big Transitions', 'Moves, job changes, loss, and other life events — and how couples adapt together.', 'Moves, job changes, loss, and other life events — and how couples adapt together.', '7 min', 5, ARRAY['Vulnerability-stress-adaptation model']::text[], '{"introduction": "Big life events — moving, starting or losing a job, a death in the family, retirement — test relationships. Routines break down, stress rises, and partners may react differently. Transitions are also chances to grow closer, depending on how couples adapt.", "sections": [{"title": "Stress, vulnerability, and adaptation", "body": "One helpful way to think about relationships is that outcomes depend on three things: the stressful events couples face, the vulnerabilities each partner brings (like their history or temperament), and how they adapt together — how they communicate, solve problems, and support each other. Couples can''t control every event, but they can shape how they adapt.", "research": {"text": "A major review proposed that relationship outcomes depend on the interaction of stressful events, enduring vulnerabilities, and adaptive processes like communication and support.", "source": "Karney & Bradbury, Psychological Bulletin", "year": 1995}}, {"title": "Adapting together", "body": "During transitions, it helps to expect some strain, lower the bar for everything else, and check in more often than usual. Partners may process change differently: one may want to plan, the other may need time to grieve what''s being left behind. Both reactions are valid.", "tip": {"title": "During a big change", "steps": ["Name the transition and acknowledge it''s hard.", "Check in weekly about how each of you is feeling.", "Let go of non-essential commitments for a while."]}}], "conclusion": "You can''t avoid life''s big transitions, but you can face them as a team. How you adapt together shapes the relationship you''ll have on the other side."}'::jsonb, '["Transitions test relationships by breaking routines", "Outcomes depend on events, vulnerabilities, and adaptation", "Partners may process change differently", "More check-ins and lower expectations help during change"]'::jsonb, '[{"title": "Transition check-in", "description": "Talk about a current or upcoming change.", "duration": "15 min", "instructions": ["Name a transition you''re facing or expect soon.", "Each share what excites and worries you about it.", "Agree on how you''ll check in with each other during it."]}]'::jsonb, '{"question": "How do you tend to react to big changes?", "followUp": "What helps you feel supported during a transition?"}'::jsonb, 'draft'),
  ('health-wellness-series', 'money', 'Money as a Couple', 'Why money conflicts run deep, and how to talk about finances as a team.', 'Why money conflicts run deep, and how to talk about finances as a team.', '8 min', 6, ARRAY['Financial relationship research']::text[], '{"introduction": "Money is one of the most common sources of conflict for couples. That''s often because money isn''t just about numbers — it''s tied to security, freedom, values, and what each partner learned growing up.", "sections": [{"title": "Why money conflicts matter", "body": "Money arguments can feel especially intense because they touch deeper values: one partner may see saving as safety, while the other sees spending on experiences as living well. Neither view is wrong, but the difference needs to be talked about.", "research": {"text": "Research found that arguments about money were a stronger predictor of divorce than other common disagreements, for both husbands and wives.", "source": "Dew, Britt & Huston, Family Relations", "year": 2012}}, {"title": "Talking money as a team", "body": "Regular, calm money conversations help much more than crisis talks. Start by sharing what money means to each of you and what you learned about it growing up. Then work on practical agreements: shared goals, spending thresholds for checking in, and how you''ll handle individual spending.", "tip": {"title": "A monthly money date", "steps": ["Pick a relaxed time once a month.", "Review spending and progress toward shared goals.", "Celebrate progress and adjust plans without blame."]}}], "conclusion": "Money conversations get easier when they''re regular, calm, and grounded in understanding each other''s values. Working as a team turns money from a source of conflict into a shared project."}'::jsonb, '["Money conflicts often reflect deeper values", "Money arguments are strongly linked to relationship strain", "Regular calm conversations beat crisis talks", "Shared goals and agreements reduce conflict"]'::jsonb, '[{"title": "Money stories", "description": "Understand each other''s history and values around money.", "duration": "20 min", "instructions": ["Each share what money meant in your family growing up.", "Each share what money means to you now (security, freedom, generosity…).", "Agree on one shared financial goal and a check-in date."]}]'::jsonb, '{"question": "What does money represent to you?", "followUp": "Where do your money values and your partner''s overlap?"}'::jsonb, 'draft'),
  ('health-wellness-series', 'acceptance', 'Acceptance and Change', 'Balancing the wish to change your partner with acceptance of who they are.', 'Balancing the wish to change your partner with acceptance of who they are.', '7 min', 7, ARRAY['Integrative Behavioral Couple Therapy']::text[], '{"introduction": "Many couples spend years trying to change each other: be tidier, more spontaneous, less anxious, more talkative. Some change is possible and healthy. But relationships also need acceptance — making peace with differences that are part of who your partner is.", "sections": [{"title": "Why acceptance matters", "body": "Pushing hard for change often backfires: the partner feels criticized and resists, and the pushing partner feels unheard. Acceptance doesn''t mean giving up on all change. It means understanding the differences, seeing them with more compassion, and choosing which ones to let go.", "research": {"text": "Integrative Behavioral Couple Therapy combines strategies for change with strategies for emotional acceptance, and has shown lasting benefits for distressed couples.", "source": "Jacobson & Christensen, Integrative Couple Therapy", "year": 1996}}, {"title": "Seeing differences differently", "body": "Often the trait that frustrates you is connected to something you love. A partner''s carefulness with money may also be why they''re so dependable. Seeing the bigger picture can soften frustration and make it easier to accept — and, paradoxically, can make change easier too.", "tip": {"title": "Practicing acceptance", "steps": ["Choose one difference that has caused repeated friction.", "Ask what positive quality it might be connected to.", "Talk about what you could accept, and what you''d still like to work on."]}}], "conclusion": "Healthy relationships balance change with acceptance. Letting go of some battles makes room for the changes that truly matter — and for more compassion in between."}'::jsonb, '["Pushing for change often backfires", "Acceptance means understanding differences with compassion", "Frustrating traits are often linked to qualities you love", "Acceptance can make real change easier"]'::jsonb, '[{"title": "Two sides of a trait", "description": "Look at a difference from a new angle.", "duration": "15 min", "instructions": ["Each name one trait in your partner that sometimes frustrates you.", "Each name a quality you value that might be connected to it.", "Share what you''d like to accept and what you''d still like to discuss."]}]'::jsonb, '{"question": "What difference between you would you like to accept more fully?", "followUp": "What would acceptance feel like day to day?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Key Concepts (8 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('key-concepts-series', 'Key Concepts', 'Short introductions to the core ideas from relationship research that the rest of Bond builds on.', 'A compact tour of well-known ideas from relationship science: sentiment override, the 5:1 ratio, we-ness, attunement, interdependence, sacrifice, emotional intelligence, and how lasting change happens.', '🔑', 9, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('key-concepts-series', 'sentiment-override', 'Positive Sentiment Override', 'How the overall feeling in a relationship colors how each moment is interpreted.', 'How the overall feeling in a relationship colors how each moment is interpreted.', '5 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "The same comment — \"You''re late again\" — can feel like light teasing in one relationship and an attack in another. The difference often lies not in the words, but in the overall feeling partners have toward each other.", "sections": [{"title": "A lens on every interaction", "body": "When the overall feeling is warm, partners tend to give each other the benefit of the doubt: a sharp tone is read as stress, not contempt. This is called positive sentiment override. When the overall feeling is negative, even neutral comments can feel hostile — negative sentiment override.", "research": {"text": "The idea of sentiment override proposes that partners'' overall feelings toward each other shape how they interpret each other''s behavior, beyond what the behavior itself conveys.", "source": "Weiss, in Advances in Family Intervention, Assessment and Theory", "year": 1980}}, {"title": "Shifting the lens", "body": "The lens isn''t fixed. Everyday fondness, appreciation, and turning toward each other gradually build positive sentiment. Pausing before assuming the worst — \"Is there a kinder explanation?\" — can also help.", "tip": {"title": "Building positive sentiment", "steps": ["Share one specific appreciation every day.", "When something stings, ask what else it could mean.", "Notice the good things your partner does, out loud."]}}], "conclusion": "How partners feel about each other overall shapes how every moment is understood. Small, steady kindness builds a lens that helps couples through hard moments."}'::jsonb, '["Overall feelings color how moments are interpreted", "Positive sentiment gives partners the benefit of the doubt", "Negative sentiment makes neutral moments feel hostile", "Everyday appreciation shifts the lens over time"]'::jsonb, '[{"title": "Kinder explanations", "description": "Practice looking for generous interpretations.", "duration": "10 min", "instructions": ["Each recall a recent moment your partner''s words stung.", "Together, brainstorm possible kinder explanations.", "Share what was actually going on for you in that moment."]}]'::jsonb, '{"question": "What lens do you tend to see your partner through lately?", "followUp": "What would help it feel warmer?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'five-to-one', 'The 5:1 Ratio', 'Why positive moments need to outnumber negative ones, especially during conflict.', 'Why positive moments need to outnumber negative ones, especially during conflict.', '5 min', 2, ARRAY['Gottman Method']::text[], '{"introduction": "All couples have negative moments: complaints, irritation, disagreements. What seems to matter is not avoiding them entirely but balancing them with enough positive moments.", "sections": [{"title": "The balance that matters", "body": "In observations of couples discussing conflicts, stable couples showed roughly five positive interactions — interest, affection, humor, understanding — for every negative one. Couples heading for trouble had a much lower ratio.", "research": {"text": "Gottman''s research observing couples found that stable relationships had about five positive interactions for every negative one during conflict discussions.", "source": "Gottman, What Predicts Divorce?", "year": 1994}}, {"title": "Positivity during conflict", "body": "The ratio is a useful guide, not a rule to count. It suggests that during disagreements, small positives — a touch, a nod, humor, \"that''s a fair point\" — help keep conflict from turning into a fight. Outside of conflict, the ratio of positive to negative is typically even higher in happy couples.", "tip": {"title": "Adding positives in conflict", "steps": ["Acknowledge what makes sense in your partner''s view.", "Use gentle humor if it feels natural to both of you.", "Show affection even while disagreeing."]}}], "conclusion": "Negative moments are part of every relationship. Keeping them outnumbered by warmth, humor, and understanding helps couples handle conflict without losing connection."}'::jsonb, '["Negative moments are normal", "Stable couples show about five positives per negative in conflict", "The ratio is a guide, not a scorecard", "Small positives keep disagreements from escalating"]'::jsonb, '[{"title": "Positive moments inventory", "description": "Notice how many positive moments you share.", "duration": "Throughout one day", "instructions": ["For one day, each notice positive moments between you.", "In the evening, share the ones you noticed.", "Choose one positive habit to add during your next disagreement."]}]'::jsonb, '{"question": "What positive moments help you most during a disagreement?", "followUp": "What could you add more of?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'we-ness', 'We-ness', 'How seeing yourselves as a team shapes how you face life together.', 'How seeing yourselves as a team shapes how you face life together.', '5 min', 3, ARRAY['Oral history research']::text[], '{"introduction": "Listen to how couples tell the story of their relationship. Some talk mostly about \"we\" — what we went through, what we decided. Others talk more about \"I\" and \"he\" or \"she.\" That difference can reveal a lot about how connected partners feel.", "sections": [{"title": "Telling your story as a team", "body": "Couples who describe their history with a strong sense of \"we\" — pride in getting through hard times together, fondness for each other — tend to have more stable relationships. We-ness reflects a shared identity: we''re in this together.", "research": {"text": "A study of couples'' accounts of their relationship history found that expressions of we-ness and fondness predicted which couples stayed together years later.", "source": "Buehlman, Gottman & Katz, Journal of Family Psychology", "year": 1992}}, {"title": "Building we-ness", "body": "We-ness grows when couples face challenges together, celebrate shared accomplishments, and talk about their future as a joint project. Remembering and retelling \"our\" stories — how you met, what you got through — also strengthens it.", "tip": {"title": "Strengthening your \"we\"", "steps": ["Retell the story of how you met.", "Remember a hard time you got through together.", "Talk about a goal that belongs to both of you."]}}], "conclusion": "We-ness is the sense that your relationship is a team. Telling your story together, and facing the future together, keeps that team strong."}'::jsonb, '["How couples tell their story reveals connection", "We-ness and fondness predict relationship stability", "Shared challenges and goals build we-ness", "Retelling \"our\" stories strengthens it"]'::jsonb, '[{"title": "Our story", "description": "Retell the story of your relationship together.", "duration": "20 min", "instructions": ["Together, tell the story of how you met and fell for each other.", "Recall one hard time you got through and how you did it.", "Name one thing you''re proud of as a couple."]}]'::jsonb, '{"question": "What moment in your relationship makes you proudest of \"us\"?", "followUp": "What would you like the next chapter of your story to include?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'attunement', 'Attunement', 'Tuning in to each other''s emotional world, especially in hard moments.', 'Tuning in to each other''s emotional world, especially in hard moments.', '6 min', 4, ARRAY['Gottman Method']::text[], '{"introduction": "Attunement means tuning in to your partner''s emotional world — noticing what they feel, turning toward it, and responding with understanding. It''s especially important when emotions are negative.", "sections": [{"title": "The skills of attunement", "body": "Gottman describes attunement as a combination of skills: awareness of your partner''s emotions, turning toward them, tolerance of their feelings (even when they differ from yours), trying to understand, non-defensive listening, and empathy. Together, these help partners feel seen.", "research": {"text": "Gottman''s work on trust describes attunement as the core way partners build trust — by tuning in to each other''s emotions, especially negative ones, with understanding.", "source": "Gottman, The Science of Trust", "year": 2011}}, {"title": "Attunement in practice", "body": "Attunement is easiest when emotions are mild and hardest when they''re about you. When your partner is upset with you, try to understand their experience before explaining yours. Staying curious — \"Tell me more\" — is a powerful form of attunement.", "tip": {"title": "Tuning in", "steps": ["Notice your partner''s mood when you reunite.", "Ask about their feelings, not just events.", "Understand before explaining."]}}], "conclusion": "Attunement is how partners come to feel truly known. Tuning in to each other''s emotions, especially in hard moments, is one of the most powerful ways to build trust."}'::jsonb, '["Attunement means tuning in to each other''s emotions", "It combines awareness, tolerance, understanding, and empathy", "It matters most during negative emotions", "Curiosity is a powerful form of attunement"]'::jsonb, '[{"title": "Emotion check-in", "description": "Practice tuning in to each other''s feelings.", "duration": "10 min", "instructions": ["Each share a feeling you had today and what caused it.", "The listener asks one curious follow-up question.", "The listener reflects the feeling they heard."]}]'::jsonb, '{"question": "When do you feel most understood by your partner?", "followUp": "What helps you tune in to them?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'interdependence', 'Interdependence', 'How partners'' choices affect each other, and why commitment grows from shared investment.', 'How partners'' choices affect each other, and why commitment grows from shared investment.', '6 min', 5, ARRAY['Interdependence theory']::text[], '{"introduction": "In a close relationship, what one person does affects the other. A late night at work changes dinner plans; a new job changes both partners'' lives. Interdependence theory looks at how partners navigate these shared outcomes.", "sections": [{"title": "Shared outcomes", "body": "Because partners'' outcomes are linked, many situations involve a choice between what''s best for me in the moment and what''s best for us. Over time, couples who increasingly think in terms of \"us\" tend to become more committed and more willing to accommodate each other.", "research": {"text": "Interdependence theory describes how partners'' outcomes are linked and how, over time, they learn to transform self-interest into concern for shared outcomes.", "source": "Rusbult & Van Lange, Annual Review of Psychology", "year": 2003}}, {"title": "Commitment and accommodation", "body": "Committed partners are more likely to respond constructively when the other behaves badly — for example, staying calm rather than snapping back. This \"accommodation\" isn''t about being a pushover; it''s about protecting the relationship from spiraling negativity.", "tip": {"title": "Thinking in \"us\"", "steps": ["Before a decision, ask: \"How does this affect us?\"", "When your partner snaps, try responding calmly once.", "Talk about what you''re each investing in the relationship."]}}], "conclusion": "Relationships link partners'' lives together. Learning to think in terms of \"us\" builds commitment and helps couples respond to each other with care."}'::jsonb, '["Partners'' choices affect each other", "Couples learn to weigh shared outcomes over self-interest", "Commitment makes constructive responses more likely", "Accommodation protects against spiraling negativity"]'::jsonb, '[{"title": "Us decisions", "description": "Talk about how you make decisions that affect both of you.", "duration": "15 min", "instructions": ["Each name a recent decision that affected your partner.", "Talk about how you considered each other.", "Agree on which kinds of decisions you want to make together."]}]'::jsonb, '{"question": "What decisions do you like to make together?", "followUp": "When do you feel most like a team?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'sacrifice', 'Sacrifice and Motivation', 'Why the reason behind a sacrifice matters as much as the sacrifice itself.', 'Why the reason behind a sacrifice matters as much as the sacrifice itself.', '6 min', 6, ARRAY['Approach-avoidance motivation research']::text[], '{"introduction": "Every relationship involves sacrifice: going to a partner''s family event, taking on extra chores, compromising on where to live. Sacrifice can build closeness — or resentment. Research suggests the difference often lies in why we sacrifice.", "sections": [{"title": "Approach and avoidance", "body": "People sacrifice for different reasons. Some do it to gain something positive — to make their partner happy or to feel closer (approach motives). Others do it to avoid something negative — conflict, or a partner''s disappointment (avoidance motives). Approach-motivated sacrifices tend to feel better and support the relationship.", "research": {"text": "Research found that sacrifices made for approach reasons were linked to greater well-being and relationship satisfaction, while sacrifices made to avoid negative outcomes were linked to lower satisfaction and more conflict.", "source": "Impett, Gable & Peplau, Journal of Personality and Social Psychology", "year": 2005}}, {"title": "Healthy sacrifice", "body": "Healthy sacrifice feels like a gift rather than a debt. If you notice you often sacrifice to avoid conflict, it may help to share your needs more openly. And when your partner sacrifices for you, noticing and appreciating it makes a big difference.", "tip": {"title": "Making sacrifice a gift", "steps": ["Before a sacrifice, notice why you''re making it.", "If it''s mostly to avoid conflict, consider sharing your needs.", "Thank your partner for sacrifices they make for you."]}}], "conclusion": "Sacrifice is part of loving someone. Making it for the right reasons — and noticing when your partner does — keeps it a source of closeness."}'::jsonb, '["Sacrifice is part of every relationship", "Why you sacrifice matters as much as what you sacrifice", "Approach motives support well-being; avoidance motives can harm it", "Appreciating a partner''s sacrifices matters"]'::jsonb, '[{"title": "Sacrifice appreciation", "description": "Notice and appreciate sacrifices you make for each other.", "duration": "10 min", "instructions": ["Each name a sacrifice your partner has made for you recently.", "Thank them specifically for it.", "Share whether any of your own sacrifices feel more like debts than gifts."]}]'::jsonb, '{"question": "What sacrifice has your partner made that you''re grateful for?", "followUp": "Is there a sacrifice you make that you''d like to talk about?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'emotional-intelligence', 'Emotional Intelligence', 'Recognizing, understanding, and managing emotions — your own and your partner''s.', 'Recognizing, understanding, and managing emotions — your own and your partner''s.', '6 min', 7, ARRAY['Emotional intelligence research']::text[], '{"introduction": "Emotional intelligence is the ability to recognize, understand, and manage emotions — your own and other people''s. In relationships, it helps partners notice what they feel, express it clearly, and respond to each other with understanding.", "sections": [{"title": "The core abilities", "body": "Emotional intelligence includes several related abilities: perceiving emotions accurately, using emotions to guide thinking, understanding how emotions work, and managing emotions in yourself and others. These are skills, not fixed traits, and they can grow with practice.", "research": {"text": "Salovey and Mayer introduced the concept of emotional intelligence as a set of abilities for perceiving, understanding, and managing emotions.", "source": "Salovey & Mayer, Imagination, Cognition and Personality", "year": 1990}}, {"title": "Emotional intelligence in the relationship", "body": "In everyday life, emotional intelligence looks like naming your feelings precisely (\"disappointed\" rather than just \"bad\"), noticing when you''re getting overwhelmed, and recognizing your partner''s feelings even when they don''t say them outright.", "tip": {"title": "Growing emotional intelligence", "steps": ["Try naming your feelings more precisely.", "Notice body signs of rising emotion (tight chest, clenched jaw).", "Ask your partner: \"What are you feeling right now?\""]}}], "conclusion": "Emotional intelligence helps partners understand themselves and each other. It''s a set of skills that grows with practice — and every relationship benefits from it."}'::jsonb, '["Emotional intelligence involves perceiving, understanding, and managing emotions", "These abilities are skills that can grow", "Precise emotion words help partners understand each other", "Noticing early signs of rising emotion helps prevent escalation"]'::jsonb, '[{"title": "Feelings vocabulary", "description": "Practice naming feelings precisely.", "duration": "10 min", "instructions": ["Each describe a recent moment using as precise a feeling word as you can.", "Share what that feeling was like in your body.", "Notice together how precise words change understanding."]}]'::jsonb, '{"question": "Which feelings are easiest and hardest for you to name?", "followUp": "How could naming them help your relationship?"}'::jsonb, 'draft'),
  ('key-concepts-series', 'how-couples-change', 'How Couples Change', 'Why small, repeated habits create lasting change more reliably than big resolutions.', 'Why small, repeated habits create lasting change more reliably than big resolutions.', '6 min', 8, ARRAY['Habit formation research']::text[], '{"introduction": "Many couples start with big resolutions — \"We''ll have date night every week!\" — that fade after a few weeks. Lasting change tends to come from smaller, repeated habits that fit into everyday life.", "sections": [{"title": "Habits take time", "body": "Research on habit formation suggests that new behaviors become automatic gradually, often over weeks or months. Missing a day here and there doesn''t ruin the process. What matters is repeating the behavior consistently in a similar context.", "research": {"text": "A study of habit formation found that new behaviors became automatic over a period of about two months on average, with wide variation, and that missing an occasional day did not derail progress.", "source": "Lally, van Jaarsveld, Potts & Wardle, European Journal of Social Psychology", "year": 2010}}, {"title": "Small habits, big difference", "body": "Choose small changes tied to existing routines: a hug when you get home, a question over breakfast, a weekly check-in on Sunday evening. Small, reliable habits add up — and they''re much easier to keep than big commitments.", "tip": {"title": "Starting a couple habit", "steps": ["Pick one small behavior.", "Tie it to something you already do every day.", "Be patient; give it at least a couple of months."]}}], "conclusion": "Lasting change in a relationship rarely comes from grand gestures. It comes from small, repeated habits that make connection part of everyday life."}'::jsonb, '["Big resolutions often fade", "New habits become automatic gradually", "Missing a day doesn''t derail progress", "Small habits tied to existing routines work best"]'::jsonb, '[{"title": "One small habit", "description": "Choose one couple habit to build over the next two months.", "duration": "10 min", "instructions": ["Each suggest one small habit that would help your relationship.", "Choose one together and tie it to an existing routine.", "Set a reminder to check in on it in a month."]}]'::jsonb, '{"question": "What small habit would make the biggest difference for you two?", "followUp": "What would help you stick with it?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

-- Repair & Communication (4 modules)
INSERT INTO learning_series (series_key, title, summary, description, icon, sort_order, review_status) VALUES ('repair-and-communication', 'Repair & Communication', 'How to start hard conversations, listen well, set boundaries, and build shared rhythm.', 'Practical skills for the conversations that matter most: soft startups, listening and validation, boundaries and trust repair, and the rituals that keep couples in sync.', '🛠️', 10, 'draft')
ON CONFLICT (series_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;
INSERT INTO learning_series_modules (series_key, module_key, title, summary, description, duration, sort_order, frameworks, content, key_takeaways, exercises, reflection, review_status) VALUES
  ('repair-and-communication', 'rc-1', 'Soft Startups and Hard Conversations', 'Learn how to raise difficult topics without triggering instant defensiveness.', 'Learn how to raise difficult topics without triggering instant defensiveness.', '12 min', 1, ARRAY['Gottman Method']::text[], '{"introduction": "Hard conversations usually fail before the actual issue is discussed. The first 30 seconds matter because they set the nervous system tone for everything that follows.\n\nA soft startup is not weakness. It is a way of making truth easier to hear.", "sections": [{"title": "Lead with the real issue, not the charge", "body": "When people start with blame, the other person hears threat before meaning. When they start with the issue and their feeling, the conversation stays usable for longer.\n\nTry to lead with \"I feel\" and \"I need\" instead of the story your anger is telling."}, {"title": "One sentence can change the whole tone", "body": "A better opening is specific, short, and non-accusatory. It names what happened, why it matters, and what kind of response would help.\n\nThat keeps the conversation focused on repair instead of defense.", "example": {"scenario": "You feel dismissed when your partner checks their phone mid-conversation.", "dialogue": "\"I want to talk about something that matters to me. When I feel interrupted, I start to shut down. Can we put the phone away for ten minutes?\"", "analysis": "The message is direct, but it does not attack character. That makes it easier to hear."}}, {"title": "Timing matters as much as wording", "body": "Even a good opening can fail if someone is flooded, hungry, tired, or distracted. Part of communication skill is choosing a moment when both people can actually listen.\n\nThe goal is not to avoid hard topics. It is to choose a moment when the topic has a chance."}], "conclusion": "Soft starts help relationships stay open long enough to solve real problems instead of fighting about tone."}'::jsonb, '["The first 30 seconds shape the conversation", "Lead with feeling and need, not blame", "Timing matters as much as wording"]'::jsonb, '[{"title": "Rewrite a Startup", "description": "Turn one recent complaint into a softer opening.", "duration": "10 min", "instructions": ["Write the opening you actually used", "Underline the part that sounds blaming or global", "Rewrite it as a feeling + need + request", "Practice saying the new version out loud"]}]'::jsonb, '{"question": "How do you usually start hard conversations?", "followUp": "What would make your opening feel clearer and less threatening?"}'::jsonb, 'draft'),
  ('repair-and-communication', 'rc-2', 'Listening, Validation, and Repair Language', 'Learn the skills that make people feel understood before solutions start.', 'Learn the skills that make people feel understood before solutions start.', '11 min', 2, ARRAY['Active listening', 'Gottman Method']::text[], '{"introduction": "Most people do not calm down because they are given a solution. They calm down because they feel understood.\n\nListening is not passive. It is an active signal that the relationship is safe enough for the truth.", "sections": [{"title": "Mirror before you interpret", "body": "Good listening begins with reflecting back what you heard in simple language. That keeps you from arguing with a version of the story that only exists in your head.\n\nMirroring is not agreeing. It is checking whether you actually understood."}, {"title": "Validation is not surrender", "body": "Validation means the other person’s feelings make sense in context. It does not mean they are right about everything or that you must give in.\n\nIt is often the fastest way to lower defensiveness so both people can keep talking.", "tip": {"title": "Validation formula", "steps": ["Say what you heard", "Name the feeling", "Acknowledge why it makes sense", "Ask if you got it right"]}}, {"title": "Repair language keeps the door open", "body": "Repair language includes phrases like \"I see what you mean,\" \"I missed that,\" \"Let me try again,\" and \"Help me understand better.\"\n\nThese words matter because they show the relationship matters more than being perfectly right in the moment."}], "conclusion": "The goal of listening is not to win agreement. It is to make understanding strong enough that the conversation can continue."}'::jsonb, '["People calm down when they feel understood", "Validation is not the same as agreement", "Repair language should be normal, not rare"]'::jsonb, '[{"title": "Mirror and Validate", "description": "Practice reflecting your partner before adding your own view.", "duration": "12 min", "instructions": ["Pick one recent frustration", "Write a one-sentence reflection of your partner’s point", "Add one validating sentence", "Only then add your perspective"]}]'::jsonb, '{"question": "What do you need most when you are upset: solutions, reassurance, or understanding?", "followUp": "How can you make that need easier for your partner to meet?"}'::jsonb, 'draft'),
  ('repair-and-communication', 'rc-3', 'Boundaries, Autonomy, and Trust Repair', 'Use boundaries to protect connection instead of using them to create distance.', 'Use boundaries to protect connection instead of using them to create distance.', '13 min', 3, ARRAY['Differentiation (Bowen family systems)', 'Gottman Method']::text[], '{"introduction": "Boundaries are not walls. They are agreements that help two people stay safe, respected, and clear.\n\nHealthy couples do not treat boundaries as rejection. They treat them as structure.", "sections": [{"title": "Boundaries reduce resentment", "body": "When people know what is okay and what is not, they stop guessing and start cooperating. Boundaries protect energy, time, privacy, and emotional bandwidth.\n\nWithout them, resentment tends to grow in the dark."}, {"title": "Autonomy strengthens trust", "body": "Trust gets stronger when both people can be themselves without constant monitoring. That includes having individual space, separate interests, and room to make choices.\n\nAutonomy does not weaken the relationship. It makes the relationship less brittle."}, {"title": "Repair after a crossed line", "body": "If a boundary gets crossed, repair has to include ownership, a clear change, and time. The point is not to punish. The point is to restore safety.\n\nA boundary that cannot be talked about is not really a healthy boundary.", "example": {"scenario": "One partner keeps bringing up sensitive topics in front of other people.", "analysis": "The repair needs both an apology and a new agreement about privacy."}}], "conclusion": "Boundaries and trust work best together: boundaries clarify what is safe, and trust grows when those agreements are respected."}'::jsonb, '["Boundaries protect connection when they are clear", "Autonomy helps trust stay healthy", "Crossed boundaries require ownership and a real change"]'::jsonb, '[{"title": "Boundary Reset", "description": "Choose one boundary that needs to be clearer or kinder.", "duration": "10 min", "instructions": ["Name one line you wish was clearer", "Rewrite it without blame", "Add what you need instead", "Agree on how you will follow it"]}]'::jsonb, '{"question": "Where does your relationship need clearer structure?", "followUp": "What boundary would actually make you feel more loved, not less?"}'::jsonb, 'draft'),
  ('repair-and-communication', 'rc-4', 'Rituals, Desire, and Shared Rhythm', 'Create repeatable habits that keep intimacy and connection from fading into routine.', 'Create repeatable habits that keep intimacy and connection from fading into routine.', '12 min', 4, ARRAY['Gottman Method']::text[], '{"introduction": "Relationships need rhythm. Without a shared pattern, even loving partners can drift into logistics, exhaustion, and disconnection.\n\nRituals are not fluff. They are how connection becomes dependable.", "sections": [{"title": "Rituals make closeness easier", "body": "A ritual is a repeatable moment that tells both people, \"We still matter to each other.\" It can be a morning check-in, a nightly walk, a Sunday reset, or a goodbye kiss that never gets skipped.\n\nThe smaller and more consistent the ritual, the more powerful it usually is."}, {"title": "Desire grows with safety and anticipation", "body": "For many couples, desire improves when pressure goes down and warmth goes up. Safety, playfulness, and predictability all help create more room for connection.\n\nThe point is not to force chemistry. It is to create the conditions where chemistry has a chance."}, {"title": "Make your rhythm visible", "body": "Write down the habits that make your relationship feel alive, then protect them with the same seriousness you would give any other important part of life.\n\nWhat gets scheduled tends to survive.", "tip": {"title": "Build one ritual", "steps": ["Pick a moment that already happens", "Attach one loving action to it", "Keep it short", "Repeat it for two weeks before changing anything"]}}], "conclusion": "Shared rhythm turns intimacy into a pattern instead of a hope. That is what helps relationships feel steady over time."}'::jsonb, '["Rituals create dependable connection", "Safety and anticipation both matter for desire", "Short repeated habits are stronger than big occasional gestures"]'::jsonb, '[{"title": "Ritual Design", "description": "Design one small ritual that fits your life right now.", "duration": "10 min", "instructions": ["Choose one existing daily moment", "Add one intentional connection habit to it", "Keep it short enough to repeat easily", "Try it for 14 days"]}]'::jsonb, '{"question": "What rhythm would make your relationship feel more alive?", "followUp": "What could you start doing consistently this week?"}'::jsonb, 'draft')
ON CONFLICT (series_key, module_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, description = EXCLUDED.description, duration = EXCLUDED.duration, sort_order = EXCLUDED.sort_order, frameworks = EXCLUDED.frameworks, content = EXCLUDED.content, key_takeaways = EXCLUDED.key_takeaways, exercises = EXCLUDED.exercises, reflection = EXCLUDED.reflection, review_status = EXCLUDED.review_status;

